// warp: integer column maxima/minima are order-free, so a butterfly gives the serial result.
TEMPO_HD int tempo_warp_max(int v) {
  for (int o = 16; o > 0; o >>= 1) v = imax(v, __shfl_xor_sync(TEMPO_FULL, v, o));
  return v;
