        + T.png_rcs[k] + T.png_gde[k] - T.pnr_gml[k]) * orho;
    qbten[k] = qbten[k] + (T.pbg_scw[k] + T.pbg_rfz[k] + T.pbg_gcw[k] + T.pbg_rci[k]
