  TempoTend& T = W.T;
  const int nz1 = nz + 1;
  int substeps_sedi, ktop_sedi, n;
  float semi_sedi_factor; float  tempc; float  tc0;
  bool do_micro = false, supersaturated = false;
  const float t0 = PS(t0);
  // warp: the column scalars of W are written by the lead lane only.
