    warm_rain(P, C, nz, W.rhof, W.l_qc, W.rc, W.nc, W.ilamc, W.mvd_c, W.l_qr, W.rr, W.nr, W.mvd_r, T);
    rain_snow_rain_graupel(P, C, nz, W.temp, W.l_qr, W.rr, W.nr, W.ilamr, W.l_qs, W.rs, W.l_qg,
                           W.rg, W.ng, W.ilamg, W.idx_bg, T);
