// ===================== adreal.cuh =====================
// SPDX-License-Identifier: Apache-2.0
// ======================================================================
// adreal_warp.cuh: executed-branch tape types for the generated TEMPO
// tangent and adjoint in the forecast's own warp shape (TEMPO_WARP 1: one
// 32-lane warp runs one column, level k on lane (k-1)%32). Autodiff physics
// rung, lane L5. Private program code.
//
// AR<T> is the same active type as the serial build (primal v computed by
// the forward's own operation on the same operands, node id i, 0 = constant).
// What changes is who records: every lane records the nodes of the
// statements it executes. Node n of lane L has id (n << 5) | L (n = 1, 2,
// ... per lane), and the tape of a column is one block [n][32 lanes] that
// starts at base[column], so an id is its own offset inside the block and
// stores of the 32 lanes coalesce.
//
// Every TEMPO_SYNC of the column code is ad_sync(): it closes a phase (each
// lane stores its node counter), synchronises the warp and starts the next
// phase on a common row (the warp's largest counter). The forward reads
// another level only after a TEMPO_SYNC, so a node reads another lane's node
// only across a phase boundary. The tangent therefore sweeps the phases in
// order (pull, no write conflicts) and the adjoint sweeps them in reverse;
// a contribution to another lane's node is held in the lane's outbox and
// applied at the end of the phase in fixed lane order, so two reverse runs
// are bitwise equal. The reverse checks the phase rule on every cross-lane
// edge and reports a fault instead of a wrong answer.
// ======================================================================
// ---- x20 T7 hand stage (mk_t7swap.py)
// SPDX-License-Identifier: Apache-2.0
// x20 TEMPO stage T7 (cond-evap): hand reverse of cloud_condensation and rain_evaporation for the fused,
// tape-free TEMPO reverse (adjoint-20x, ADJOINT-JEDI-2026-11-07, private).
//
// Shape: register-resident, level-local. Each call takes ONE level's primal inputs (the values the forward
// substep had when it called cloud_condensation / rain_evaporation), recomputes every forward intermediate in
// registers with the forward's own float/double expressions (so every branch is the forward's branch), and
// pushes the output cotangents back to the inputs in float64. No tape, no global loads except the TEMPO
// parameter tables the forward itself reads, no syncs. The only cross-level coupling is cloud_condensation's
// RETURN level (kstop, an int, the warp minimum); see t7_cond_kstop().
//
// Partials are the tape's own: d(x*y) = (double)y etc., d exp(a) = exp((double)a), d log(x) = 1/(double)x,
// d pow(x,c) = c pow(x, c-1), d fabs(x) = signbit(x) ? -1 : 1, tmax/tmin pass the executed arm (ties go to the
// second argument, as tmax(a,b) = a > b ? a : b). Only the summation order differs from the generated sweep.
//
// NOTE (stage map correction): the saturation adjustment has a FIXED 3 Newton iterations
// (module_mp_tempo_main.F90:1958-2026), not a recorded iteration count. Nothing integer needs recording for T7:
// kstop is recomputed from ssatw, the activation/table indices from the primal inputs.
//
// Include after the forward TEMPO source (global namespace: TempoParams, TempoCtx, PS/PI/PA*, tempo_exp,
// tempo_log, tempo_pow, tmax/tmin, imax/imin, tnint, get_cloud_table_index, TEMPO_LEVELS, tempo_warp_min).
//
// Frozen-mask note: with AD_FRZ_MASK 0xc6 (the pk120/pkg18m2 bundles) bits 0, 3, 4, 14 and 15 are OFF, so
// xnc, t1_evap, n0_r and all four T7 outputs are live; this file differentiates them all. If a deck turns one
// of those bits on, the integrator zeroes the matching term (marked FRZ(n) below).

// ------------------------------------------------------------------------------------------- condensation
struct T7CondX {           // one level's primal inputs to cloud_condensation
  float rho, temp, w1d, ssatw, lvap, tcond, diffu, lvt2, nwfa, qv, qvs, rc, nc;
  bool l_qc;
};
struct T7CondXb {          // cotangents. temp, ssatw, lvap, tcond, diffu have no derivative path in
  double rho, w1d, lvt2, nwfa, qv, qvs, rc, nc;   // condensation (branch / table index only): not carried
};

// cloud_condensation's warp RETURN level: levels k >= kstop are untouched (outputs keep their incoming value
// and their cotangent passes through). Same code as the forward, on primal floats.
__device__ __forceinline__ int t7_cond_kstop(const TempoParams& P, int nz, const float* ssatw) {
  int kstop = nz + 1;
  TEMPO_LEVELS(k, nz) if (fabsf(ssatw[k]) < PS(eps)) { kstop = k; break; }
#if TEMPO_WARP
  kstop = tempo_warp_min(kstop);
#endif
  return kstop;
}

// activate_cloud_number (land = nullptr), primal + reverse in one: returns the value; act_b != 0 adds the
// cotangents of nwfa and w1d (temp only picks the table row).
__device__ __forceinline__ float t7_activate(const TempoParams& P, float temp, float w1d, float nwfa,
                                             double act_b, double* nwfa_b, double* w1d_b) {
  const int ntb_arc = PI(ntb_arc), ntb_arw = PI(ntb_arw), ntb_art = PI(ntb_art);
  float n_local = nwfa * 1.e-6f; bool n_live = true;
  if (n_local >= PA1(ta_na, ntb_arc)) { n_local = PA1(ta_na, ntb_arc) - 1.0f; n_live = false; }
  else if (n_local <= PA1(ta_na, 1)) { n_local = PA1(ta_na, 1) + 1.0f; n_live = false; }
  int n;
  for (n = 2; n <= ntb_arc; ++n) if (n_local >= PA1(ta_na, n - 1) && n_local < PA1(ta_na, n)) break;
  const int i = n;
  const float x1 = tempo_log(PA1(ta_na, i - 1)), x2 = tempo_log(PA1(ta_na, i));
  float w_local = w1d; bool w_live = true;
  if (w_local >= PA1(ta_ww, ntb_arw)) { w_local = PA1(ta_ww, ntb_arw) - 1.0f; w_live = false; }
  else if (w_local <= PA1(ta_ww, 1)) { w_local = PA1(ta_ww, 1) + 0.001f; w_live = false; }
  for (n = 2; n <= ntb_arw; ++n) if (w_local >= PA1(ta_ww, n - 1) && w_local < PA1(ta_ww, n)) break;
  const int j = n;
  const float y1 = tempo_log(PA1(ta_ww, j - 1)), y2 = tempo_log(PA1(ta_ww, j));
  const int kk = imax(1, imin(tnint((temp - PA1(ta_tk, 1)) * 0.1f) + 1, ntb_art));
  const int l = 3, m = 2;
  const float a = PA5(tnccn_act, i - 1, j - 1, kk, l, m), b = PA5(tnccn_act, i, j - 1, kk, l, m);
  const float c = PA5(tnccn_act, i, j, kk, l, m), d = PA5(tnccn_act, i - 1, j, kk, l, m);
  const float nx = tempo_log(n_local), wy = tempo_log(w_local);
  const float dx = x2 - x1, dy = y2 - y1;
  const float t = (nx - x1) / dx, u = (wy - y1) / dy;
  const float omt = 1.0f - t, omu = 1.0f - u;
  const float f0 = omt * omu * a + t * omu * b + t * u * c + omt * u * d;
  const float fraction = (f0 > 0.0f) ? f0 : 0.0f;      // tmax(f0, 0.f): tie -> the constant
  if (act_b != 0.0) {
    *nwfa_b += act_b * (double)fraction;
    if (f0 > 0.0f) {
      const double fb = act_b * (double)nwfa;
      const double tb = fb * (-(double)omu * a + (double)omu * b + (double)u * c - (double)u * d);
      const double ub = fb * (-(double)omt * a - (double)t * b + (double)t * c + (double)omt * d);
      if (n_live) *nwfa_b += (tb / (double)dx) / (double)n_local * (double)1.e-6f;
      if (w_live) *w1d_b += (ub / (double)dy) / (double)w_local;
    }
  }
  return nwfa * fraction;
}

// One level of cloud_condensation (k < kstop), primal + optional reverse. prw_in/pnc_in are the incoming T
// values (T is zeroed each substep). Primal: writes *prw, *pnc bit for bit as the forward. Reverse (xb set):
// given prw_b, pnc_b, adds the input cotangents to *xb and the pass-through parts to *prw_in_b / *pnc_in_b.
__device__ __forceinline__ void t7_cond_level(const TempoParams& P, const TempoCtx& C, const T7CondX& x,
    double prw_in, double pnc_in, double* prw, double* pnc,
    double prw_b = 0.0, double pnc_b = 0.0, T7CondXb* xb = nullptr, double* prw_in_b = nullptr,
    double* pnc_in_b = nullptr) {
  const float orv = PS(orv); const float pi = PS(pi);
  const float gidt = C.global_inverse_dt;
  // ---- forward, registers
  const float orho = 1.0f / x.rho;
  const float num0 = x.qv - x.qvs, den0 = 1.0f + x.lvt2 * x.qvs;
  float cl[4], ea[3], ee[3], fc[3], df[3];
  const float m1v = x.qvs * x.lvt2;
  cl[0] = num0 / den0;
#pragma unroll
  for (int n = 0; n < 3; ++n) {
    ea[n] = x.lvt2 * cl[n];
    ee[n] = tempo_exp(ea[n]);
    fc[n] = x.qvs * ee[n] - x.qv + cl[n];
    df[n] = m1v * ee[n] + 1.0f;
    cl[n + 1] = cl[n] - fc[n] / df[n];
  }
  const float clap = cl[3];
  const float xrc = x.rc + clap * x.rho;
  double o_prw = prw_in, o_pnc = pnc_in;
  int br = 0;            // 1: B (xrc <= r1), 2: A1 (activation), 3: A2 (evaporating cloud), 4: A only
  float act = 0.0f, dn = 0.0f, s05g = 0.0f, nrc99 = 0.0f, nnc99 = 0.0f;
  double tnc = 0.0; bool a2_x = false, a2_nx = false;
  if (xrc > PS(r1)) {
    o_prw = clap * gidt;
    if (clap > PS(eps)) {
      br = 2;
      act = t7_activate(P, x.temp, x.w1d, x.nwfa, 0.0, nullptr, nullptr);
      const float xnc = (PS(nt_c_min) > act) ? PS(nt_c_min) : act;     // tmax(nt_c_min, act)
      dn = xnc - x.nc;
      s05g = 0.5f * (dn + fabsf(dn)) * gidt;
      o_pnc = s05g * orho;
    } else if (x.l_qc && x.ssatw < -1.e-6f && clap < -PS(eps)) {
      br = 3;
      const float otemp = 1.0f / x.temp;
      const float rvs = x.rho * x.qvs;
      const float rvs_p = rvs * otemp * (x.lvap * otemp * orv - 1.0f);
      const float rvs_pp = rvs * (otemp * (x.lvap * otemp * orv - 1.0f) * otemp * (x.lvap * otemp * orv - 1.0f)
                         + (-2.0f * x.lvap * otemp * otemp * otemp * orv) + otemp * otemp);
      const float gamsc = x.lvap * x.diffu / x.tcond * rvs_p;
      float alphsc = 0.5f * (gamsc / (1.0f + gamsc)) * (gamsc / (1.0f + gamsc)) * rvs_pp / rvs_p * rvs / rvs_p;
      alphsc = tmax(1.e-9f, alphsc);
      float xsat = x.ssatw;
      if (fabsf(xsat) < 1.e-9f) xsat = 0.0f;
      const float t1_evap = 2.0f * pi * (1.0f - alphsc * xsat + 2.0f * alphsc * alphsc * xsat * xsat
                          - 5.0f * alphsc * alphsc * alphsc * xsat * xsat * xsat) / (1.0f + gamsc);
      const double dc_star = sqrt(-2.0 * C.global_dt * t1_evap / (2.0 * pi) * 4.0 * x.diffu * x.ssatw * rvs
                                  / PS(rho_w));
      const int idx_d = imax(1, imin((int)(1.e6f * dc_star), PI(nbc)));
      int idx_c, idx_n;
      get_cloud_table_index(P, x.rc, x.nc, &idx_c, &idx_n);
      nrc99 = -x.rc * 0.99f;
      const float px = nrc99 * orho * gidt;
      a2_x = (double)px > o_prw;                          // tmax(px, prw): px > prw ? px : prw
      if (a2_x) o_prw = px;
      nnc99 = -x.nc * 0.99f;
      const float qx = nnc99 * orho * gidt;
      tnc = PA3(tnc_wev, idx_d, idx_c, idx_n);
      const double qy = -tnc * orho * gidt;
      a2_nx = (double)qx > qy;
      o_pnc = a2_nx ? (double)qx : qy;
    } else {
      br = 4;
    }
  } else {
    br = 1;
    o_prw = -x.rc * orho * gidt;
    o_pnc = -x.nc * orho * gidt;
  }
  *prw = o_prw; *pnc = o_pnc;
  if (!xb) return;
  // ---- reverse
  double orho_b = 0.0, clap_b = 0.0;
  const double g = (double)gidt, ro = (double)orho;
  switch (br) {
    case 1:   // prw = ((-rc)*orho)*gidt ; pnc = ((-nc)*orho)*gidt
      xb->rc += -prw_b * g * ro;  orho_b += prw_b * g * (double)(-x.rc);
      xb->nc += -pnc_b * g * ro;  orho_b += pnc_b * g * (double)(-x.nc);
      break;
    case 2: { // prw = clap*gidt ; pnc = ((0.5*(dn+|dn|))*gidt)*orho
      clap_b += prw_b * g;
      orho_b += pnc_b * (double)s05g;
      const double sb = pnc_b * ro * g * 0.5;
      const double dnb = sb * (1.0 + (signbit(dn) ? -1.0 : 1.0));
      xb->nc -= dnb;
      if (!(PS(nt_c_min) > act) && dnb != 0.0)          // FRZ(3): xnc frozen -> drop this term
        t7_activate(P, x.temp, x.w1d, x.nwfa, dnb, &xb->nwfa, &xb->w1d);
      break; }
    case 3:   // prw = tmax(((-rc*.99)*orho)*gidt, clap*gidt) ; pnc = tmax(((-nc*.99)*orho)*gidt, ((-tnc)*orho)*gidt)
      if (a2_x) { xb->rc += -prw_b * g * ro * (double)0.99f; orho_b += prw_b * g * (double)nrc99; }
      else clap_b += prw_b * g;
      if (a2_nx) { xb->nc += -pnc_b * g * ro * (double)0.99f; orho_b += pnc_b * g * (double)nnc99; }
      else orho_b += pnc_b * g * (-tnc);
      break;
    case 4:   // prw = clap*gidt ; pnc untouched
      clap_b += prw_b * g;
      if (pnc_in_b) *pnc_in_b += pnc_b;
      break;
  }
  (void)prw_in_b;   // prw is written on every k < kstop
  if (clap_b != 0.0) {
    // xrc only picks the branch. Newton, reversed.
    double lvt2_b = 0.0, qv_b = 0.0, qvs_b = 0.0;
#pragma unroll
    for (int n = 2; n >= 0; --n) {
      // cl[n+1] = cl[n] - fc/df
      const double fcb = -clap_b / (double)df[n];
      const double dfb = clap_b * (double)fc[n] / ((double)df[n] * (double)df[n]);
      double clb = clap_b;
      // df = (qvs*lvt2)*ee + 1
      const double m1b = dfb * (double)ee[n];
      double eb = dfb * (double)m1v;
      qvs_b += m1b * (double)x.lvt2; lvt2_b += m1b * (double)x.qvs;
      // fc = (qvs*ee - qv) + cl
      qvs_b += fcb * (double)ee[n]; eb += fcb * (double)x.qvs; qv_b -= fcb; clb += fcb;
      // ee = exp(ea), ea = lvt2*cl (the forward takes this exp twice; both copies' cotangents are in eb)
      const double eab = eb * exp((double)ea[n]);
      lvt2_b += eab * (double)cl[n]; clb += eab * (double)x.lvt2;
      clap_b = clb;
    }
    // cl[0] = (qv - qvs)/(1 + lvt2*qvs)
    const double nb = clap_b / (double)den0, db = -clap_b * (double)num0 / ((double)den0 * (double)den0);
    qv_b += nb; qvs_b -= nb; lvt2_b += db * (double)x.qvs; qvs_b += db * (double)x.lvt2;
    xb->qv += qv_b; xb->qvs += qvs_b; xb->lvt2 += lvt2_b;
  }
  xb->rho += -orho_b / ((double)x.rho * (double)x.rho);
}

// ------------------------------------------------------------------------------------------- evaporation
struct T7EvapX {           // one level's primal inputs to rain_evaporation
  float rho, temp, ssatw, lvap, tcond, diffu, vsc2, rhof2, qv, qvs, rr, nr;
  double ilamr;
  double prw_vcd, prr_gml; // branch only (this substep's condensation and melting rates)
  bool l_qr;
};
struct T7EvapXb {
  double rho, temp, ssatw, lvap, tcond, diffu, vsc2, rhof2, qv, qvs, rr, nr, ilamr;
};

// One level of rain_evaporation, primal + optional reverse. Same conventions as t7_cond_level.
__device__ __forceinline__ void t7_evap_level(const TempoParams& P, const TempoCtx& C, const T7EvapX& x,
    double prv_in, double pnr_in, double* prv, double* pnr,
    double prv_b = 0.0, double pnr_b = 0.0, T7EvapXb* xb = nullptr, double* prv_in_b = nullptr,
    double* pnr_in_b = nullptr) {
  const float orv = PS(orv); const float pi = PS(pi);
  const float gidt = C.global_inverse_dt;
  const bool on = x.l_qr && (x.ssatw < -PS(eps)) && x.prw_vcd <= 0.0f;
  if (!on) {
    *prv = prv_in; *pnr = pnr_in;
    if (xb) { if (prv_in_b) *prv_in_b += prv_b; if (pnr_in_b) *pnr_in_b += pnr_b; }
    return;
  }
  // ---- forward, registers (the forward's expression trees, split only into named nodes)
  const float orho = 1.0f / x.rho;
  const float tempc = x.temp - PS(t0);
  const float otemp = 1.0f / x.temp;
  const float rvs = x.rho * x.qvs;
  const float a1 = x.lvap * otemp, a2 = a1 * orv, L = a2 - 1.0f;
  const float r1 = rvs * otemp, rvs_p = r1 * L;
  const float b1 = otemp * L, b2 = b1 * otemp, b3 = b2 * L;
  const float c1 = -2.0f * x.lvap, c2 = c1 * otemp, c3 = c2 * otemp, c4 = c3 * otemp, c5 = c4 * orv;
  const float d1 = otemp * otemp;
  const float s1 = b3 + c5, s2 = s1 + d1, rvs_pp = rvs * s2;
  const float g1 = x.lvap * x.diffu, g2 = g1 / x.tcond, gamsc = g2 * rvs_p;
  const float h = 1.0f + gamsc, q1 = gamsc / h;
  const float e1 = 0.5f * q1, e2 = e1 * q1, e3 = e2 * rvs_pp, e4 = e3 / rvs_p, e5 = e4 * rvs, al0 = e5 / rvs_p;
  const bool al_live = !(1.e-9f > al0);
  const float al = al_live ? al0 : 1.e-9f;                       // tmax(1e-9, al0)
  const bool xs_live = !(-1.e-9f < x.ssatw);
  const float xs = xs_live ? x.ssatw : -1.e-9f;                  // tmin(-1e-9, ssatw)
  const float p1 = al * xs, p2 = 1.0f - p1;
  const float k1 = 2.0f * al, k2 = k1 * al, k3 = k2 * xs, k4 = k3 * xs, p3 = p2 + k4;
  const float n1 = 5.0f * al, n2 = n1 * al, n3 = n2 * al, n4 = n3 * xs, n5 = n4 * xs, n6 = n5 * xs;
  const float poly = p3 - n6;
  const float tw = 2.0f * pi, t1n = tw * poly, t1_evap = t1n / h;
  const float rro = x.rr * orho;
  const bool e1p = (x.qv / x.qvs < 0.95f && rro <= 1.e-8f);
  double o_prv;
  double lamr = 0, pw1 = 0, n0_r = 0, f3 = 0, f4 = 0, pw10 = 0, lb = 0, pw11 = 0, B = 0, prv0 = 0, pm = 0, prv1 = 0;
  float n0a = 0, f1 = 0, nss = 0, f2 = 0, v1 = 0, v2 = 0, rm1 = 0, rm2 = 0, rate_max = 0, ef = 1.0f;
  bool rm_1 = false, rate_sel = false, melt = false, ef_live = false;
  if (e1p) {
    o_prv = rro * gidt;
  } else {
    lamr = 1.0f / x.ilamr;
    pw1 = tempo_pow(lamr, PA1(cre, 2));
    n0a = x.nr * PS(org2); n0_r = n0a * pw1;
    f1 = t1_evap * x.diffu; nss = -x.ssatw; f2 = f1 * nss; f3 = f2 * n0_r; f4 = f3 * rvs;
    pw10 = tempo_pow(x.ilamr, PA1(cre, 10)); const double B1 = PS(t1_qr_ev) * pw10;
    v1 = PS(t2_qr_ev) * x.vsc2; v2 = v1 * x.rhof2;
    lb = lamr + 0.5f * PS(fv_r); pw11 = tempo_pow(lb, (-PA1(cre, 11))); const double B2 = v2 * pw11;
    B = B1 + B2; prv0 = f4 * B;
    rm1 = rro * gidt; rm2 = (x.qvs - x.qv) * gidt;
    rm_1 = rm1 < rm2; rate_max = rm_1 ? rm1 : rm2;               // tmin(rm1, rm2)
    pm = prv0 * orho;
    rate_sel = (double)rate_max < pm; prv1 = rate_sel ? (double)rate_max : pm;
    o_prv = prv1;
    melt = x.prr_gml > 0.0f;
    if (melt) {
      const float ef0 = tmin(1.0f, 0.01f + (0.99f - 0.01f) * (tempc / 20.0f));
      ef_live = !(1.0f < 0.01f + (0.99f - 0.01f) * (tempc / 20.0f));
      ef = ef0;
      o_prv = prv1 * ef;
    }
  }
  const float nx99 = x.nr * 0.99f, px = nx99 * orho * gidt;
  const double pn = o_prv * x.nr, py = pn / x.rr;
  const bool pnr_x = (double)px < py;                            // tmin(px, py)
  *prv = o_prv; *pnr = pnr_x ? (double)px : py;
  if (!xb) return;
  // ---- reverse
  const double g = (double)gidt, ro = (double)orho;
  double orho_b = 0.0, prv_bb = prv_b;
  if (pnr_x) { xb->nr += pnr_b * g * ro * (double)0.99f; orho_b += pnr_b * g * (double)nx99; }
  else {
    prv_bb += pnr_b * (double)x.nr / (double)x.rr; xb->nr += pnr_b * o_prv / (double)x.rr;
    xb->rr += -pnr_b * pn / ((double)x.rr * (double)x.rr);
  }
  double t1e_b = 0.0, rvs_b = 0.0, temp_b = 0.0;
  if (e1p) {
    xb->rr += prv_bb * g * ro; orho_b += prv_bb * g * (double)x.rr;
  } else {
    double prv1_b = prv_bb;
    if (melt) {
      prv1_b = prv_bb * (double)ef;
      if (ef_live) temp_b += prv_bb * prv1 * (double)(0.99f - 0.01f) / 20.0;
    }
    double prv0_b = 0.0;
    if (rate_sel) {
      if (rm_1) { xb->rr += prv1_b * g * ro; orho_b += prv1_b * g * (double)x.rr; }
      else { xb->qvs += prv1_b * g; xb->qv -= prv1_b * g; }
    } else { prv0_b = prv1_b * ro; orho_b += prv1_b * prv0; }
    if (prv0_b != 0.0) {
      const double f4b = prv0_b * B, Bb = prv0_b * f4;
      // B2 = ((t2*vsc2)*rhof2)*pow(lb, -cre11)
      const double v2b = Bb * pw11, pw11b = Bb * (double)v2;
      xb->rhof2 += v2b * (double)v1; xb->vsc2 += v2b * (double)x.rhof2 * (double)PS(t2_qr_ev);
      const double e11 = (double)(-PA1(cre, 11));
      double lamr_b = pw11b * (e11 * pow(lb, e11 - 1.0));
      // B1 = t1*pow(ilamr, cre10)
      const double e10 = (double)PA1(cre, 10);
      double il_b = Bb * (double)PS(t1_qr_ev) * (e10 * pow(x.ilamr, e10 - 1.0));
      // f4 = f3*rvs, f3 = f2*n0_r, f2 = f1*(-ssatw), f1 = t1_evap*diffu
      const double f3b = f4b * (double)rvs; rvs_b += f4b * f3;
      const double f2b = f3b * n0_r, n0b = f3b * (double)f2;
      const double f1b = f2b * (double)nss; xb->ssatw -= f2b * (double)f1;
      t1e_b += f1b * (double)x.diffu; xb->diffu += f1b * (double)t1_evap;     // FRZ(4): t1_evap frozen -> t1e_b = 0
      // n0_r = (nr*org2)*pow(lamr, cre2)                                        FRZ(0): n0_r frozen -> n0b = 0
      xb->nr += n0b * pw1 * (double)PS(org2);
      const double e2c = (double)PA1(cre, 2);
      lamr_b += n0b * (double)n0a * (e2c * pow(lamr, e2c - 1.0));
      il_b += -lamr_b / (x.ilamr * x.ilamr);
      xb->ilamr += il_b;
    }
  }
  // t1_evap = ((2 pi)*poly)/(1+gamsc)
  double rvs_p_b = 0.0, otemp_b = 0.0, lvap_b = 0.0;
  if (t1e_b != 0.0) {
    double gam_b = 0.0, rvs_pp_b = 0.0, L_b = 0.0;
    const double t1nb = t1e_b / (double)h; gam_b += -t1e_b * (double)t1n / ((double)h * (double)h);
    const double polyb = t1nb * (double)tw;
    double al_b = 0.0, xs_b = 0.0;
    const double n6b = -polyb, p3b = polyb;
    const double n5b = n6b * xs; xs_b += n6b * (double)n5;
    const double n4b = n5b * xs; xs_b += n5b * (double)n4;
    const double n3b = n4b * xs; xs_b += n4b * (double)n3;
    const double n2b = n3b * al; al_b += n3b * (double)n2;
    const double n1b = n2b * al; al_b += n2b * (double)n1;
    al_b += n1b * 5.0;
    const double k4b = p3b, p2b = p3b;
    const double k3b = k4b * xs; xs_b += k4b * (double)k3;
    const double k2b = k3b * xs; xs_b += k3b * (double)k2;
    const double k1b = k2b * al; al_b += k2b * (double)k1;
    al_b += k1b * 2.0;
    const double p1b = -p2b; al_b += p1b * (double)xs; xs_b += p1b * (double)al;
    if (xs_live) xb->ssatw += xs_b;
    if (al_live) {
      const double e5b = al_b / (double)rvs_p; rvs_p_b += -al_b * (double)e5 / ((double)rvs_p * (double)rvs_p);
      const double e4b = e5b * (double)rvs; rvs_b += e5b * (double)e4;
      const double e3b = e4b / (double)rvs_p; rvs_p_b += -e4b * (double)e3 / ((double)rvs_p * (double)rvs_p);
      const double e2b = e3b * (double)rvs_pp; rvs_pp_b += e3b * (double)e2;
      const double e1b = e2b * (double)q1; double q_b = e2b * (double)e1;
      q_b += e1b * 0.5;
      // q1 = gamsc/(1+gamsc), taken twice in the forward (same value): both copies' cotangents are in q_b
      gam_b += q_b / (double)h; gam_b += -q_b * (double)gamsc / ((double)h * (double)h);
    }
    // gamsc = ((lvap*diffu)/tcond)*rvs_p
    const double g2b = gam_b * (double)rvs_p; rvs_p_b += gam_b * (double)g2;
    const double g1b = g2b / (double)x.tcond; xb->tcond += -g2b * (double)g1 / ((double)x.tcond * (double)x.tcond);
    lvap_b += g1b * (double)x.diffu; xb->diffu += g1b * (double)x.lvap;
    // rvs_pp = rvs*(((otemp*L)*otemp)*L + ((((-2 lvap)*otemp)*otemp)*otemp)*orv + otemp*otemp)
    rvs_b += rvs_pp_b * (double)s2; const double s2b = rvs_pp_b * (double)rvs;
    otemp_b += 2.0 * s2b * (double)otemp;
    const double c4b = s2b * (double)orv;
    const double c3b = c4b * (double)otemp; otemp_b += c4b * (double)c3;
    const double c2b = c3b * (double)otemp; otemp_b += c3b * (double)c2;
    const double c1b = c2b * (double)otemp; otemp_b += c2b * (double)c1;
    lvap_b += -2.0 * c1b;
    const double b2b = s2b * (double)L; L_b += s2b * (double)b2;
    const double b1b = b2b * (double)otemp; otemp_b += b2b * (double)b1;
    otemp_b += b1b * (double)L; L_b += b1b * (double)otemp;
    // rvs_p = (rvs*otemp)*L
    const double r1b = rvs_p_b * (double)L; L_b += rvs_p_b * (double)r1;
    rvs_b += r1b * (double)otemp; otemp_b += r1b * (double)rvs;
    // L = (lvap*otemp)*orv - 1
    const double a1b = L_b * (double)orv;
    lvap_b += a1b * (double)otemp; otemp_b += a1b * (double)x.lvap;
  }
  xb->lvap += lvap_b;
  xb->rho += rvs_b * (double)x.qvs; xb->qvs += rvs_b * (double)x.rho;
  temp_b += -otemp_b / ((double)x.temp * (double)x.temp);
  xb->temp += temp_b;
  xb->rho += -orho_b / ((double)x.rho * (double)x.rho);
  (void)prv_in_b; (void)pnr_in_b; (void)a2; (void)b3; (void)c5; (void)d1; (void)s1; (void)p2; (void)k4; (void)p3;
  (void)rm2; (void)rate_max;
}

// ------------------------------------------------------------------------------- tendency accumulation
// The linear block after each process in tempo_main_column, reversed (the W.*ten cotangents pass through):
//   cond: qvten -= prw; qcten += prw; ncten += pnc; nwfaten -= pnc; tten += (lvap*ocp)*prw
//   evap: qrten -= prv; qvten += prv; nrten -= pnr; nwfaten += pnr; tten -= (lvap*ocp)*prv
// lvap/ocp are the values the forward used at that point (after condensation's TEMPO_THERMO for evap).
struct T7TenB { double qv, qc, nc, nwfa, t, qr, nr; };   // cotangents of the W.*ten accumulators at this level
__device__ __forceinline__ void t7_cond_tend_rev(float lvap, float ocp, double prw, const T7TenB& tb,
                                                 double* prw_b, double* pnc_b, double* lvap_b, double* ocp_b) {
  const float lo = lvap * ocp;
  *prw_b += -tb.qv + tb.qc + tb.t * (double)lo;
  *pnc_b += tb.nc - tb.nwfa;
  const double lob = tb.t * prw;
  *lvap_b += lob * (double)ocp; *ocp_b += lob * (double)lvap;
}
__device__ __forceinline__ void t7_evap_tend_rev(float lvap, float ocp, double prv, const T7TenB& tb,
                                                 double* prv_b, double* pnr_b, double* lvap_b, double* ocp_b) {
  const float lo = lvap * ocp;
  *prv_b += -tb.qr + tb.qv - tb.t * (double)lo;
  *pnr_b += -tb.nr + tb.nwfa;
  const double lob = -tb.t * prv;
  *lvap_b += lob * (double)ocp; *ocp_b += lob * (double)lvap;
}

#ifndef AD_BLOCK
#define AD_BLOCK 128
#endif
#define AD_WARP_SHAPE 1
#define AD_NCNT 8 // per thread: nodes, branch bits, int entries, overflow bits, phases, max cross-lane edges in one phase, 0, 0

struct AdTape {
  int* a;              // parent 1 (-1 marks an input leaf)
  int* b;              // parent 2 (0 = none)
  double* pa;          // partial wrt parent 1
  double* pb;          // partial wrt parent 2
  unsigned* br;        // branch bits [word][thread]
  int* il;             // integer log [entry][thread]
  int* count;          // [thread][AD_NCNT]
  const unsigned* rbr; // replay: branch bits to impose (null: free run)
  const int* ril;      // replay: integer log to impose
  long long T;         // threads in the tile (log interleave stride)
  long long bcap;      // branch-bit capacity per thread (bits; 0: off)
  long long icap;      // integer-log capacity per thread (0: off)
  const long long* base; // per column: first slot of its tape block (null: count only, no tape)
  const int* ccap;     // per column: node capacity per lane
  int* phase;          // per column [pcap][32]: lane node counter at each ad_sync (null: not kept)
  long long pcap;      // phases per column
  int* mark;           // count pass: [nmark][thread][3] node counter, phase counter, max cross-lane edges (null: off)
  long long nmark;
};
__device__ AdTape g_ad;
// tempo-once lane-major tape: slot of node id (n << 5) | L in a column block of C rows per lane.
#define AD_OFF(id, C) ((long long)((id) & 31) * (long long)(C) + (long long)((id) >> 5))
__shared__ int ad_n_s[AD_BLOCK];
__shared__ int ad_b_s[AD_BLOCK];
__shared__ int ad_i_s[AD_BLOCK];
__shared__ int ad_o_s[AD_BLOCK];
__shared__ int ad_p_s[AD_BLOCK];
__shared__ int ad_r_s[AD_BLOCK];
__shared__ int ad_m_s[AD_BLOCK];
__shared__ int ad_u_s[AD_BLOCK];
__shared__ int ad_v_s[AD_BLOCK];
__shared__ long long ad_q_s[AD_BLOCK];
__shared__ int ad_c_s[AD_BLOCK];
// tempo-adjoint-v2 lane capacities: lane L's rows start at ad_lo_s[warp base + L] inside its column block
__shared__ long long ad_lo_s[AD_BLOCK];
#define AD_LOFF(id) (ad_lo_s[(threadIdx.x & ~31u) + ((id) & 31)] + (long long)((id) >> 5))
// g_ad.ccap[w * 32 + lane]: this lane's capacity; returns its first row in the block, *tot the block's rows (whole warp)
__device__ __forceinline__ long long ad_lanecap(long long w, int lane, int* cap, long long* tot) {
  const int c = g_ad.ccap[w * 32 + lane];
  long long incl = c;
  for (int o = 1; o < 32; o <<= 1) { const long long y = __shfl_up_sync(0xffffffffu, incl, o); if (lane >= o) incl += y; }
  const long long off = incl - c;
  ad_lo_s[threadIdx.x] = off;
  *cap = c; *tot = __shfl_sync(0xffffffffu, incl, 31);
  __syncwarp();
  return off;
}

__device__ __forceinline__ long long ad_tid() { return (long long)blockIdx.x * blockDim.x + threadIdx.x; }
__device__ __forceinline__ int ad_lane() { return (int)(threadIdx.x & 31u); }
__device__ __forceinline__ void ad_begin() {
  const int x = threadIdx.x;
  ad_n_s[x] = 1; ad_b_s[x] = 0; ad_i_s[x] = 0; ad_o_s[x] = 0; ad_p_s[x] = 0; ad_r_s[x] = 0; ad_m_s[x] = 0; ad_u_s[x] = 0; ad_v_s[x] = 0;
}
__device__ __forceinline__ void ad_end() {
  const long long t = ad_tid(); const int x = threadIdx.x;
  int* c = g_ad.count + AD_NCNT * t;
  c[0] = ad_n_s[x]; c[1] = ad_b_s[x]; c[2] = ad_i_s[x]; c[3] = ad_o_s[x];
  c[4] = ad_p_s[x]; c[5] = max(ad_m_s[x], ad_r_s[x]); c[6] = ad_u_s[x]; c[7] = ad_v_s[x];
}
__device__ __noinline__ int ad_push(int a, double pa, int b, double pb) {
  const int x = threadIdx.x, lane = x & 31;
  const int n = ad_n_s[x]++;
  if (a > 0) { ad_u_s[x]++; if (b) ad_v_s[x]++; }
  if (a > 0 && (a & 31) != lane) ad_r_s[x]++;
  if (b > 0 && (b & 31) != lane) ad_r_s[x]++;
  if (g_ad.base) {
    if (n < ad_c_s[x]) {
      const long long o = ad_q_s[x] + n;
      g_ad.a[o] = a; g_ad.b[o] = b; g_ad.pa[o] = pa; g_ad.pb[o] = pb;
    } else {
      ad_o_s[x] |= 1;
    }
  }
  if (n >= (1 << 26)) ad_o_s[x] |= 16;
  return (n << 5) | lane;
}
__device__ __forceinline__ int ad_node1(int a, double pa) {
  return a ? ad_push(a, pa, 0, 0.0) : 0;
}
__device__ __forceinline__ int ad_node2(int a, double pa, int b, double pb) {
  if (!a) return b ? ad_push(b, pb, 0, 0.0) : 0;
  if (!b) return ad_push(a, pa, 0, 0.0);
  return ad_push(a, pa, b, pb);
}
__device__ __forceinline__ int ad_leaf() { return ad_push(-1, 0.0, 0, 0.0); }
// Phase boundary: the warp's TEMPO_SYNC. Each lane stores where its nodes of the phase end, then every
// lane's counter moves to the warp maximum, so the next phase starts on the same row for all 32 lanes:
// lanes that run the same statements then store to one row (coalesced), and the sweeps walk the rows of
// a phase together. The skipped slots between a lane's end and the next start are never read.
__device__ __noinline__ void ad_sync() {
  const int x = threadIdx.x;
  const int p = ad_p_s[x]++;
  const int n = ad_n_s[x];
  if (g_ad.phase) {
    const long long w = ad_tid() >> 5;
    if (p < g_ad.pcap) g_ad.phase[(w * g_ad.pcap + p) * 32 + (x & 31)] = n;
    else ad_o_s[x] |= 8;
  }
  ad_m_s[x] = max(ad_m_s[x], ad_r_s[x]); ad_r_s[x] = 0;
  __syncwarp();
  (void)n; // tempo-adjoint-v2 packed rows: the next phase starts right after this lane's last node
}
// Count pass: counters at the start of every substep (and at the end of the launch).
__device__ __forceinline__ void ad_mark(int i) {
  const int x = threadIdx.x;
  if (g_ad.mark && i < g_ad.nmark) {
    int* m = g_ad.mark + ((long long)i * g_ad.T + ad_tid()) * 3;
    m[0] = ad_n_s[x]; m[1] = ad_p_s[x]; m[2] = max(ad_m_s[x], ad_r_s[x]);
  }
  ad_m_s[x] = 0;
}
// Branch and integer logs, per thread exactly as the serial build.
__device__ __noinline__ bool ad_bit(bool r) {
  const int n = ad_b_s[threadIdx.x]++;
  if (n < g_ad.bcap) {
    const long long o = (long long)(n >> 5) * g_ad.T + ad_tid();
    if (g_ad.rbr) r = (g_ad.rbr[o] >> (n & 31)) & 1u;
    if (r) g_ad.br[o] |= 1u << (n & 31);
  } else if (g_ad.bcap > 0) {
    ad_o_s[threadIdx.x] |= 2;
  }
  return r;
}
__device__ __noinline__ long long ad_int(long long v) {
  const int n = ad_i_s[threadIdx.x]++;
  if (n < g_ad.icap) {
    const long long o = (long long)n * g_ad.T + ad_tid();
    if (g_ad.ril) v = g_ad.ril[o];
    g_ad.il[o] = (int)v;
  } else if (g_ad.icap > 0) ad_o_s[threadIdx.x] |= 4;
  return v;
}

// ---------------------------------------------------------------- traits
// AR and every overload live in namespace adr: argument-dependent lookup then
// finds them from the active column code, and never the forward's own global
// templates (tmax, tempo_pow), which would tie with the active copies.
namespace adr {
template<class T> struct ad_arith { static const bool value = false; };
template<> struct ad_arith<float> { static const bool value = true; };
template<> struct ad_arith<double> { static const bool value = true; };
template<> struct ad_arith<int> { static const bool value = true; };
template<> struct ad_arith<unsigned> { static const bool value = true; };
template<> struct ad_arith<long> { static const bool value = true; };
template<> struct ad_arith<unsigned long> { static const bool value = true; };
template<> struct ad_arith<long long> { static const bool value = true; };
template<> struct ad_arith<unsigned long long> { static const bool value = true; };
template<> struct ad_arith<short> { static const bool value = true; };
template<bool B, class T = void> struct ad_if {};
template<class T> struct ad_if<true, T> { typedef T type; };
template<class T> T ad_val();

template<class T> struct AR {
  T v; int i;
  AR() = default;
  __device__ __forceinline__ AR(T x) : v(x), i(0) {}
  template<class S, class = typename ad_if<ad_arith<S>::value>::type>
  __device__ __forceinline__ AR(S x) : v((T)x), i(0) {}
  template<class U> __device__ __forceinline__ AR(const AR<U>& o) : v((T)o.v), i(o.i) {}
  __device__ __forceinline__ explicit operator int() const { return (int)ad_int((int)v); }
  __device__ __forceinline__ explicit operator long long() const { return (long long)ad_int((long long)v); }
  __device__ __forceinline__ explicit operator long() const { return (long)ad_int((long)v); }
  __device__ __forceinline__ explicit operator unsigned() const { return (unsigned)ad_int((unsigned)v); }
  __device__ __forceinline__ explicit operator bool() const { return ad_bit((bool)v); }
};
template<class T> struct ad_is_ar { static const bool value = false; };
template<class T> struct ad_is_ar<AR<T> > { static const bool value = true; };
template<class T> __device__ __forceinline__ AR<T> ad_mk(T v, int i) { AR<T> z; z.v = v; z.i = i; return z; }

// ---------------------------------------------------------------- arithmetic
#define AD_BIN(OP, PA, PB)                                                                         \
template<class A, class B> __device__ __forceinline__ AR<decltype(ad_val<A>() OP ad_val<B>())>    \
operator OP(const AR<A>& x, const AR<B>& y) {                                                      \
  const double xa = (double)x.v, yb = (double)y.v; (void)xa; (void)yb;                             \
  return ad_mk(x.v OP y.v, ad_node2(x.i, (PA), y.i, (PB))); }                                      \
template<class A, class S, class = typename ad_if<ad_arith<S>::value>::type>                       \
__device__ __forceinline__ AR<decltype(ad_val<A>() OP ad_val<S>())> operator OP(const AR<A>& x, S y) { \
  const double xa = (double)x.v, yb = (double)y; (void)xa; (void)yb;                               \
  return ad_mk(x.v OP y, ad_node1(x.i, (PA))); }                                                   \
template<class S, class B, class = typename ad_if<ad_arith<S>::value>::type>                       \
__device__ __forceinline__ AR<decltype(ad_val<S>() OP ad_val<B>())> operator OP(S x, const AR<B>& y) { \
  const double xa = (double)x, yb = (double)y.v; (void)xa; (void)yb;                               \
  return ad_mk(x OP y.v, ad_node1(y.i, (PB))); }
AD_BIN(+, 1.0, 1.0)
AD_BIN(-, 1.0, -1.0)
AD_BIN(*, yb, xa)
AD_BIN(/, 1.0 / yb, -xa / (yb * yb))
#undef AD_BIN

template<class A> __device__ __forceinline__ AR<A> operator-(const AR<A>& x) { return ad_mk((A)(-x.v), ad_node1(x.i, -1.0)); }
template<class A> __device__ __forceinline__ AR<A> operator+(const AR<A>& x) { return x; }

#define AD_CMP(OP)                                                                                 \
template<class A, class B> __device__ __forceinline__ bool operator OP(const AR<A>& x, const AR<B>& y) { \
  return ad_bit(x.v OP y.v); }                                                \
template<class A, class S, class = typename ad_if<ad_arith<S>::value>::type>                       \
__device__ __forceinline__ bool operator OP(const AR<A>& x, S y) { return ad_bit(x.v OP y); } \
template<class S, class B, class = typename ad_if<ad_arith<S>::value>::type>                       \
__device__ __forceinline__ bool operator OP(S x, const AR<B>& y) { return ad_bit(x OP y.v); }
AD_CMP(<) AD_CMP(>) AD_CMP(<=) AD_CMP(>=) AD_CMP(==) AD_CMP(!=)
#undef AD_CMP

// Compound assignment: the C++ rule (compute in the promoted type, convert back).
#define AD_CAS(OP)                                                                                 \
template<class A, class Y> __device__ __forceinline__ AR<A>& operator OP##=(AR<A>& x, const Y& y) { \
  x = AR<A>(x OP y); return x; }
AD_CAS(+) AD_CAS(-) AD_CAS(*) AD_CAS(/)
#undef AD_CAS

// ---------------------------------------------------------------- rounding intrinsics
#define AD_RN2(NAME, T, OP)                                                                        \
__device__ __forceinline__ AR<T> NAME(const AR<T>& x, const AR<T>& y) { return AR<T>(x OP y); }  \
__device__ __forceinline__ AR<T> NAME(const AR<T>& x, T y) { return AR<T>(x OP y); }              \
__device__ __forceinline__ AR<T> NAME(T x, const AR<T>& y) { return AR<T>(x OP y); }
AD_RN2(__fadd_rn, float, +) AD_RN2(__fsub_rn, float, -) AD_RN2(__fmul_rn, float, *) AD_RN2(__fdiv_rn, float, /)
AD_RN2(__dadd_rn, double, +) AD_RN2(__dsub_rn, double, -) AD_RN2(__dmul_rn, double, *) AD_RN2(__ddiv_rn, double, /)
#undef AD_RN2
template<class T> __device__ __forceinline__ AR<T> ad_fma3(T z, const AR<T>& a, const AR<T>& b, const AR<T>& c) {
  const int m = ad_node2(a.i, (double)b.v, b.i, (double)a.v);
  return ad_mk(z, ad_node2(m, 1.0, c.i, 1.0));
}
__device__ __forceinline__ AR<float> __fmaf_rn(const AR<float>& a, const AR<float>& b, const AR<float>& c) {
  return ad_fma3(::__fmaf_rn(a.v, b.v, c.v), a, b, c); }
__device__ __forceinline__ AR<double> __fma_rn(const AR<double>& a, const AR<double>& b, const AR<double>& c) {
  return ad_fma3(::__fma_rn(a.v, b.v, c.v), a, b, c); }

// ---------------------------------------------------------------- unary maths
// Each primal is the forward's own function on the primal operand; the
// partial is the analytic derivative evaluated in double.
#define AD_UN(NAME, T, PRIMAL, DERIV)                                                              \
__device__ __forceinline__ AR<T> NAME(const AR<T>& x) {                                            \
  const T z = ::PRIMAL(x.v); const double xd = (double)x.v, zd = (double)z; (void)xd; (void)zd;      \
  return ad_mk(z, x.i ? ad_node1(x.i, (DERIV)) : 0); }

__device__ __forceinline__ double ad_dsqrt(double x, double z) { return x > 0.0 ? 0.5 / z : 0.0; }
__device__ double ad_digamma(double x) {
  double r = 0.0;
  if (x <= 0.0 && x == ::floor(x)) return 0.0;
  if (x < 0.0) { r = -3.14159265358979323846 / ::tan(3.14159265358979323846 * x); x = 1.0 - x; }
  while (x < 6.0) { r -= 1.0 / x; x += 1.0; }
  const double f = 1.0 / (x * x);
  return r + ::log(x) - 0.5 / x - f * (1.0 / 12 - f * (1.0 / 120 - f * (1.0 / 252 - f * (1.0 / 240 - f * (1.0 / 132)))));
}
AD_UN(sqrtf, float, sqrtf, ad_dsqrt(xd, ::sqrt(xd)))
AD_UN(sqrt, float, sqrtf, ad_dsqrt(xd, ::sqrt(xd)))
AD_UN(sqrt, double, sqrt, ad_dsqrt(xd, ::sqrt(xd)))
AD_UN(__fsqrt_rn, float, __fsqrt_rn, ad_dsqrt(xd, ::sqrt(xd)))
AD_UN(__dsqrt_rn, double, __dsqrt_rn, ad_dsqrt(xd, ::sqrt(xd)))
AD_UN(thompson_aa_expf, float, thompson_aa_expf, ::exp(xd))
AD_UN(thompson_aa_exp, double, thompson_aa_exp, ::exp(xd))
AD_UN(thompson_aa_logf, float, thompson_aa_logf, 1.0 / xd)
AD_UN(thompson_aa_log, double, thompson_aa_log, 1.0 / xd)
AD_UN(thompson_aa_log10f, float, thompson_aa_log10f, 1.0 / (xd * 2.302585092994045684))
AD_UN(thompson_aa_log10, double, thompson_aa_log10, 1.0 / (xd * 2.302585092994045684))
AD_UN(ubm_log10f, float, ubm_log10f, 1.0 / (xd * 2.302585092994045684))
AD_UN(gfk_exp, float, gfk_exp, ::exp(xd))
AD_UN(gfk_log, float, gfk_log, 1.0 / xd)
AD_UN(exp, double, exp, ::exp(xd))
AD_UN(expf, float, expf, ::exp(xd))
AD_UN(log, double, log, 1.0 / xd)
AD_UN(logf, float, logf, 1.0 / xd)
AD_UN(log10, double, log10, 1.0 / (xd * 2.302585092994045684))
AD_UN(sin, double, sin, ::cos(xd))
AD_UN(cos, double, cos, -::sin(xd))
AD_UN(glibc_cosf, float, glibc_cosf, -::sin(xd))
AD_UN(glibc_sinf, float, glibc_sinf, ::cos(xd))
AD_UN(atan, double, atan, 1.0 / (1.0 + xd * xd))
AD_UN(atanf, float, atanf, 1.0 / (1.0 + xd * xd))
AD_UN(tgammaf, float, tgammaf, ::tgamma(xd) * ad_digamma(xd))
AD_UN(tgamma, double, tgamma, ::tgamma(xd) * ad_digamma(xd))
AD_UN(gfk_tgamma, float, gfk_tgamma, ::tgamma(xd) * ad_digamma(xd))
AD_UN(fabs, double, fabs, ::signbit(xd) ? -1.0 : 1.0)
AD_UN(fabs, float, fabsf, ::signbit(xd) ? -1.0 : 1.0)
AD_UN(fabsf, float, fabsf, ::signbit(xd) ? -1.0 : 1.0)
AD_UN(floor, double, floor, 0.0)
AD_UN(floorf, float, floorf, 0.0)
AD_UN(floor, float, floorf, 0.0)
AD_UN(ceil, double, ceil, 0.0)
AD_UN(ceilf, float, ceilf, 0.0)
#undef AD_UN

__device__ __forceinline__ long lroundf(const AR<float>& x) { return (long)ad_int(::lroundf(x.v)); }
__device__ __forceinline__ long lround(const AR<double>& x) { return (long)ad_int(::lround(x.v)); }
__device__ __forceinline__ bool isnan(const AR<float>& x) { return ad_bit(::isnan(x.v)); }
__device__ __forceinline__ bool isnan(const AR<double>& x) { return ad_bit(::isnan(x.v)); }
__device__ __forceinline__ bool isinf(const AR<float>& x) { return ad_bit(::isinf(x.v)); }
__device__ __forceinline__ bool isinf(const AR<double>& x) { return ad_bit(::isinf(x.v)); }
__device__ __forceinline__ bool signbit(const AR<float>& x) { return ad_bit(::signbit(x.v)); }
__device__ __forceinline__ bool signbit(const AR<double>& x) { return ad_bit(::signbit(x.v)); }

// copysign(a, b) = |a| with the sign of b: d/da = sign(a) sign(b), d/db = 0.
template<class T> __device__ __forceinline__ AR<T> ad_copysign(const AR<T>& a, const AR<T>& b) {
  const T z = ::copysign(a.v, b.v);
  const double s = (::signbit(a.v) != ::signbit(b.v)) ? -1.0 : 1.0;
  return ad_mk(z, ad_node1(a.i, s));
}
__device__ __forceinline__ AR<double> copysign(const AR<double>& a, const AR<double>& b) { return ad_copysign(a, b); }
__device__ __forceinline__ AR<float> copysign(const AR<float>& a, const AR<float>& b) { return ad_copysign(a, b); }
__device__ __forceinline__ AR<float> copysignf(const AR<float>& a, const AR<float>& b) { return ad_copysign(a, b); }

// ---------------------------------------------------------------- binary maths
// pow: d/dx = y x^(y-1), d/dy = x^y log x (x > 0; 0 otherwise, the
// executed arm of the forward's own special cases).
__device__ __forceinline__ void ad_pow_partials(double x, double y, double z, double* px, double* py) {
  *px = (y == 0.0) ? 0.0 : (x != 0.0 ? y * ::pow(x, y - 1.0) : (y == 1.0 ? 1.0 : 0.0));
  *py = (x > 0.0) ? z * ::log(x) : 0.0;
}
template<class T> __device__ __forceinline__ AR<T> ad_pow_out(T z, const AR<T>& x, const AR<T>& y) {
  double px, py; ad_pow_partials((double)x.v, (double)y.v, (double)z, &px, &py);
  return ad_mk(z, ad_node2(x.i, px, y.i, py));
}
#define AD_POW(NAME, T)                                                                            \
__device__ __forceinline__ AR<T> NAME(const AR<T>& x, const AR<T>& y) { return ad_pow_out(::NAME(x.v, y.v), x, y); } \
__device__ __forceinline__ AR<T> NAME(const AR<T>& x, T y) { return ad_pow_out(::NAME(x.v, y), x, AR<T>(y)); } \
__device__ __forceinline__ AR<T> NAME(T x, const AR<T>& y) { return ad_pow_out(::NAME(x, y.v), AR<T>(x), y); }
AD_POW(thompson_aa_powf, float)
AD_POW(thompson_aa_pow, double)
AD_POW(gfk_pow, float)
AD_POW(pow, double)
AD_POW(powf, float)
#undef AD_POW

template<class T> __device__ __forceinline__ AR<T> ad_hypot_out(T z, const AR<T>& x, const AR<T>& y) {
  const double h = (double)z;
  const double px = h > 0.0 ? (double)x.v / h : 0.0, py = h > 0.0 ? (double)y.v / h : 0.0;
  return ad_mk(z, ad_node2(x.i, px, y.i, py));
}
__device__ __forceinline__ AR<double> thompson_aa_hypot(const AR<double>& x, const AR<double>& y) {
  return ad_hypot_out(::thompson_aa_hypot(x.v, y.v), x, y); }
template<class T> __device__ __forceinline__ AR<T> ad_atan2_out(T z, const AR<T>& y, const AR<T>& x) {
  const double xd = (double)x.v, yd = (double)y.v, r = xd * xd + yd * yd;
  return ad_mk(z, ad_node2(y.i, r > 0.0 ? xd / r : 0.0, x.i, r > 0.0 ? -yd / r : 0.0));
}
__device__ __forceinline__ AR<double> atan2(const AR<double>& y, const AR<double>& x) { return ad_atan2_out(::atan2(y.v, x.v), y, x); }
__device__ __forceinline__ AR<double> thompson_aa_atan2(const AR<double>& y, const AR<double>& x) {
  return ad_atan2_out(::thompson_aa_atan2(y.v, x.v), y, x); }

// fmin/fmax: the executed arm (the forward's own selection).
#define AD_MM(NAME, T, PRIMAL, CMP)                                                                \
__device__ __forceinline__ AR<T> NAME(const AR<T>& x, const AR<T>& y) {                            \
  T z = ::PRIMAL(x.v, y.v); const bool r0 = (x.v CMP y.v) || ::isnan(y.v); const bool r = ad_bit(r0); \
  if (r != r0) z = r ? x.v : y.v;                                                                  \
  return ad_mk(z, r ? x.i : y.i); }
AD_MM(fminf, float, fminf, <=) AD_MM(fmaxf, float, fmaxf, >=)
AD_MM(fmin, double, fmin, <=) AD_MM(fmax, double, fmax, >=)
#undef AD_MM

