__device__ __forceinline__ AR<double> NAME(const AR<double>& x) {                                  \
  const double z = ::PRIMAL(x.v); const double xd = x.v, zd = z; (void)xd; (void)zd;               \
  return ad_mk(z, x.i ? ad_node1(x.i, (DERIV)) : 0); }
