__device__ __forceinline__ long lroundf(const AR<double>& x) { return (long)ad_int(::lround(x.v)); }
#define AD_PRN(NAME, OP)                                                                           \
__device__ __forceinline__ AR<double> NAME(const AR<double>& x, const AR<double>& y) { return x OP y; } \
