TEMPO_HD AR<float> calc_gamma_series(AR<float> a, AR<float> x) {
  const int it_max = 100;
  const AR<float> smallvalue = 1.e-7f;
  AR<float> ap1 = a;
  AR<float> sum_term = 1.0f / tempo_gamma(ap1 + 1.0f);
  AR<float> sum = sum_term;
  for (int k = 1; k <= it_max; ++k) {
    ap1 = ap1 + 1.0f;
    sum_term = sum_term * x / ap1;
    sum = sum + sum_term;
    if (fabs(sum_term) < (fabs(sum) * smallvalue)) break;
  }
  return sum * tempo_pow(x, a) * tempo_exp(-x);
}

