TEMPO_HD AR<float> calc_gamma_cf(AR<float> a, AR<float> x) {
  const int it_max = 100;
  const AR<float> smallvalue = 1.e-7f;
  const AR<float> offset = 1.e-30f;
  AR<float> b = 1.0f - a + x;
  AR<float> d = 1.0f / b;
  AR<float> h0 = offset;
  AR<float> c = b + (1.0f / offset);
  AR<float> delta = c * d;
  AR<float> h = h0 * delta;
  for (int k = 1; k <= it_max; ++k) {
    AR<float> aj = k * (a - k);
    b = b + 2.0f;
    d = b + aj * d;
    if (fabs(d) < offset) d = offset;
    c = b + aj / c;
    if (fabs(c) < offset) c = offset;
    d = 1.0f / d;
    delta = c * d;
    h = h * delta;
    if (fabs(delta - 1.0f) < smallvalue) break;
  }
  return tempo_exp(-x + a * tempo_log(x)) * h / tempo_gamma(a);
}

