  nwfa[1] = PS(naccn1) + PS(naccn0) * tempo_exp(-((hgt[2] - hgt[1]) / 1000.0f) * niccn3);
  for (int k = 2; k <= nz; ++k) {
    nwfa[k] = PS(naccn1) + PS(naccn0) * tempo_exp(-((hgt[k] - hgt[1]) / 1000.0f) * niccn3);
  }
}

