  st2 = (1.2f + 1.0f / 12.0f * aval) / (1.0f + aval);
  eff = 4.0f / (re * sc) * (1.0f + 0.4f * sqrt(re) * tempo_pow(sc, 0.3333f) + 0.16f * sqrt(re) * sqrt(sc))
