// MPAS-Model-rrfs/src/core_atmosphere/physics/physics_noaa/TEMPO/src/module_mp_tempo_main.F90:1958-2026
// RRFS MPAS-Model-rrfs/src/core_atmosphere/physics/physics_noaa/TEMPO/src/module_mp_tempo_main.F90:1956-2026 @ 1d6e370e; TEMPO 9adf9ef.
TEMPO_HDN inline void cloud_condensation(const TempoParams& P, const TempoCtx& C, int nz,
    const AR<float>* rho, const AR<float>* temp, const AR<float>* w1d, const AR<float>* ssatw,
    const AR<float>* lvap, const AR<float>* tcond, const AR<float>* diffu, const AR<float>* lvt2,
    const AR<float>* nwfa, const AR<float>* qv, const AR<float>* qvs, const bool* l_qc,
    const AR<float>* rc, const AR<float>* nc, TempoTend& T) {
  // x20 T7 swap: hand primal + hand reverse Jacobian rows, one node chain per output.
  int kstop = nz + 1;
  TEMPO_LEVELS(k, nz) if (fabsf(ssatw[k].v) < PS(eps)) { kstop = k; break; }
#if TEMPO_WARP
  kstop = tempo_warp_min(kstop);
#endif
  TEMPO_LEVELS(k, nz) {
    if (k >= kstop) break;
    const T7CondX x = { rho[k].v, temp[k].v, w1d[k].v, ssatw[k].v, lvap[k].v, tcond[k].v, diffu[k].v, lvt2[k].v,
                        nwfa[k].v, qv[k].v, qvs[k].v, rc[k].v, nc[k].v, l_qc[k] };
    const double pwin = T.prw_vcd[k].v, pnin = T.pnc_wcd[k].v;
    double prw, pnc;
    T7CondXb jw = {}, jn = {}; double wpi = 0, wni = 0, npi = 0, nni = 0;
    ::t7_cond_level(P, C, x, pwin, pnin, &prw, &pnc, 1.0, 0.0, &jw, &wpi, &wni);
    ::t7_cond_level(P, C, x, pwin, pnin, &prw, &pnc, 0.0, 1.0, &jn, &npi, &nni);
    const int ids[10] = { rho[k].i, w1d[k].i, lvt2[k].i, nwfa[k].i, qv[k].i, qvs[k].i, rc[k].i, nc[k].i,
                          T.prw_vcd[k].i, T.pnc_wcd[k].i };
    const double pw[10] = { jw.rho, jw.w1d, jw.lvt2, jw.nwfa, jw.qv, jw.qvs, jw.rc, jw.nc, wpi, wni };
    const double pn[10] = { jn.rho, jn.w1d, jn.lvt2, jn.nwfa, jn.qv, jn.qvs, jn.rc, jn.nc, npi, nni };
    const int iw = t7_chain(10, ids, pw), in_ = t7_chain(10, ids, pn);
    T.prw_vcd[k] = adr::ad_mk(prw, iw);
    T.pnc_wcd[k] = adr::ad_mk(pnc, in_);
  }
}

// MPAS-Model-rrfs/src/core_atmosphere/physics/physics_noaa/TEMPO/src/module_mp_tempo_main.F90:2029-2090
// RRFS MPAS-Model-rrfs/src/core_atmosphere/physics/physics_noaa/TEMPO/src/module_mp_tempo_main.F90:2027-2090 @ 1d6e370e; TEMPO 9adf9ef.
TEMPO_HDN inline void rain_evaporation(const TempoParams& P, const TempoCtx& C, int nz,
    const AR<float>* rho, const AR<float>* temp, const AR<float>* ssatw, const AR<float>* lvap,
    const AR<float>* tcond, const AR<float>* diffu, const AR<float>* vsc2, const AR<float>* rhof2,
    const AR<float>* qv, const AR<float>* qvs, const bool* l_qr, const AR<float>* rr,
    const AR<float>* nr, const AR<double>* ilamr, TempoTend& T) {
  // x20 T7 swap: hand primal + hand reverse Jacobian rows, one node chain per output.
  TEMPO_LEVELS(k, nz) {
    const T7EvapX x = { rho[k].v, temp[k].v, ssatw[k].v, lvap[k].v, tcond[k].v, diffu[k].v, vsc2[k].v, rhof2[k].v,
                        qv[k].v, qvs[k].v, rr[k].v, nr[k].v, ilamr[k].v, T.prw_vcd[k].v, T.prr_gml[k].v, l_qr[k] };
    const double pvin = T.prv_rev[k].v, pnin = T.pnr_rev[k].v;
    double prv, pnr;
    T7EvapXb jv = {}, jn = {}; double vvi = 0, vni = 0, nvi = 0, nni = 0;
    ::t7_evap_level(P, C, x, pvin, pnin, &prv, &pnr, 1.0, 0.0, &jv, &vvi, &vni);
    ::t7_evap_level(P, C, x, pvin, pnin, &prv, &pnr, 0.0, 1.0, &jn, &nvi, &nni);
    const int ids[15] = { rho[k].i, temp[k].i, ssatw[k].i, lvap[k].i, tcond[k].i, diffu[k].i, vsc2[k].i,
                          rhof2[k].i, qv[k].i, qvs[k].i, rr[k].i, nr[k].i, ilamr[k].i, T.prv_rev[k].i, T.pnr_rev[k].i };
    const double pv[15] = { jv.rho, jv.temp, jv.ssatw, jv.lvap, jv.tcond, jv.diffu, jv.vsc2, jv.rhof2, jv.qv,
                            jv.qvs, jv.rr, jv.nr, jv.ilamr, vvi, vni };
    const double pn[15] = { jn.rho, jn.temp, jn.ssatw, jn.lvap, jn.tcond, jn.diffu, jn.vsc2, jn.rhof2, jn.qv,
                            jn.qvs, jn.rr, jn.nr, jn.ilamr, nvi, nni };
    const int iv = t7_chain(15, ids, pv), in_ = t7_chain(15, ids, pn);
    T.prv_rev[k] = adr::ad_mk(prv, iv);
    T.pnr_rev[k] = adr::ad_mk(pnr, in_);
  }
}

// MPAS-Model-rrfs/src/core_atmosphere/physics/physics_noaa/TEMPO/src/module_mp_tempo_main.F90:2093-2133.  nc1d and ncsave are optional (nullptr = absent).
// RRFS MPAS-Model-rrfs/src/core_atmosphere/physics/physics_noaa/TEMPO/src/module_mp_tempo_main.F90:2091-2133 @ 1d6e370e; TEMPO 9adf9ef.
TEMPO_HDN inline void freeze_cloud_melt_ice(const TempoParams& P, const TempoCtx& C, int nz,
    const AR<float>* temp, const AR<float>* rho, const AR<float>* ocp, const AR<float>* lvap,
    const AR<float>* qi1d, const AR<float>* ni1d, AR<float>* qiten, AR<float>* niten,
    const AR<float>* qc1d, const AR<float>* nc1d, AR<float>* qcten, AR<float>* ncten, AR<float>* tten,
    const AR<float>* ncsave) {
  AR<float> xri; AR<float>  xrc; AR<float>  lfus2; AR<float>  xnc;
  TEMPO_LEVELS(k, nz) {
    xri = tmax(0.0f, qi1d[k] + qiten[k] * C.global_dt);
    if ((temp[k] > PS(t0)) && (xri > 0.0f)) {
      qcten[k] = qcten[k] + xri * C.global_inverse_dt;
      ncten[k] = ncten[k] + ni1d[k] * C.global_inverse_dt;
      qiten[k] = qiten[k] - xri * C.global_inverse_dt;
      niten[k] = -ni1d[k] * C.global_inverse_dt;
      tten[k] = tten[k] - PS(lfus) * ocp[k] * xri * C.global_inverse_dt;
    }
    xrc = tmax(0.0f, qc1d[k] + qcten[k] * C.global_dt);
    if ((temp[k] < PS(hgfrz)) && (xrc > 0.0f)) {
      lfus2 = PS(lsub) - lvap[k];
      if (nc1d != nullptr) {
        xnc = nc1d[k] + ncten[k] * C.global_dt;
      } else if (ncsave != nullptr) {
        xnc = ncsave[k] / rho[k] + ncten[k] * C.global_dt;
      } else {
        xnc = PS(nt_c_l) / rho[k] + ncten[k] * C.global_dt;
      }
      qiten[k] = qiten[k] + xrc * C.global_inverse_dt;
      niten[k] = niten[k] + xnc * C.global_inverse_dt;
      qcten[k] = qcten[k] - xrc * C.global_inverse_dt;
      ncten[k] = ncten[k] - xnc * C.global_inverse_dt;
      tten[k] = tten[k] + lfus2 * ocp[k] * xrc * C.global_inverse_dt;
    }
  }
}

