TEMPO_HDN inline void graupel_init(const TempoParams& P, int nz, const AR<float>* rho,
    const AR<float>* qg1d, AR<float>* ng1d, AR<float>* qb1d) {
  for (int k = 1; k <= nz; ++k) {
    if (qg1d[k] > PS(r1)) {
      AR<float> rg = qg1d[k] * rho[k];
      AR<float> rb = rg * PS(meters3_to_liters) / PA1(rho_g, PI(idx_bg1));
      int idx = imax(1, imin(tnint(10.0f * rg / rb) + 1, PI(nrhg)));
      AR<float> mvd_g = 5.e-3f;
      AR<double> lamg = (3.0 + PS(mu_g) + 0.672) / mvd_g;
      AR<float> ng = PA2(cgg, 2, 1) * PS(ogg3) * rg * tpowi(lamg, 3) / PA1(am_g, idx);
      ng1d[k] = ng / rho[k];
      qb1d[k] = rb / rho[k];
    }
  }
}

