TEMPO_HDN inline void cloud_fallspeed(const TempoParams& P, const TempoCtx& C, int nz,
    const AR<float>* rhof, const AR<float>* w1d, const bool* l_qc, const AR<float>* rc,
    const AR<float>* nc, const AR<double>* ilamc, const AR<float>* dz1d, AR<float>* vt, AR<float>* vtn,
    int* ktop_sedi) {
  AR<float> hgt;
