// ===================== x20 TEMPO stage T9 (sedi-sic), hand-written (mk_t9.py) =====================
#define T9_HAVE_AR 1
// SPDX-License-Identifier: Apache-2.0
// x20 TEMPO stage T9 (sedi-sic): snow_fallspeed + sedimentation(rs); ice_fallspeed + sedimentation(ri, ni);
// cloud_fallspeed + sedimentation(rc, nc). Reverse of the forward's order in tempo_main_column (warp shape:
// one warp per column, level k on lane (k-1)%32). Private program code (ADJOINT-JEDI-2026-11-07, adjoint-20x).
//
//   Part A  level-local primal + partials, plain float/double (no AR, no tape). Shared by B and C.
//   Part B  the fused per-column reverse: __device__ functions for the integrator's no-tape TEMPO reverse.
//           Recomputes every forward intermediate from the stage-entry profiles in registers/shared; the only
//           memory it needs is the stage's true inputs plus warp scratch (no tape, no host sync, no launch).
//   Part C  (T9_HAVE_AR) the swap vehicle for the generated tempo_adw image (mk_t9.py): the forward's own
//           statements on value-only copies (same words, same branch and integer logs) plus each output's
//           local Jacobian (Part A) emitted as max(1, m-1) tape nodes. Used to grade A on the real binder.
//
// Forward facts this relies on (tempo_v303 / tempo_adw v3, warp branch):
//   * sedimentation(): sed_r = vt*xr from the pre-call profile; level nz loses its outflow; k <= ktop gains
//     sed_r[k+1] and loses sed_r[k]; each xr update clipped by tmax(limit, .) (limit wins only when limit > x);
//     xten' = xten + g (pass-through); precip' = precip + sed_r[1] dt/steps when xr'[1] > low_limit (lead lane).
//   * snow: vt fixed over its `substeps` calls (each call uses steps = substeps). ice: ONE call each for ri, ni with
//     steps = substeps (the forward's own text). cloud: one call each for rc, nc with steps = 1.
//   * vt arrays start each TEMPO substep at 0 (constants); inactive snow/ice levels copy vt from the nearest active
//     level above (tempo_next_active), inactive cloud levels keep 0. vt is not read after T9.
#ifndef T9_SEDI_SIC_CUH
#define T9_SEDI_SIC_CUH

// ============================================================================ Part A
// One level of sedimentation(). mode 1: k == nz (outflow only); 2: k <= ktop (inflow S1 = sed_r[k+1], outflow
// S0 = sed_r[k]); 0: untouched. Primal in F with the forward's exact operation order (F = float reproduces the
// forward's words under the image's --fmad=false); partials in double. d xten'/d xten = 1 always.
struct T9Sed {
  double x1, t1;                  // xr', xten' (as F)
  double x_x, x_s1, x_s0, x_dz;   // d xr' / d (xr, S1, S0, dz)
  double t_s1, t_s0, t_dz, t_rho; // d xten' / d (S1, S0, dz, rho)
};
template<class F>
__host__ __device__ __forceinline__ void t9_sed_level(int mode, F xr, F xt, F S0, F S1, F dz, F rho, F limit, F dt, int steps,
                                             T9Sed& J) {
  J.x_x = 1.0; J.x_s1 = 0.0; J.x_s0 = 0.0; J.x_dz = 0.0; J.t_s1 = 0.0; J.t_s0 = 0.0; J.t_dz = 0.0; J.t_rho = 0.0;
  if (mode == 0) { J.x1 = (double)xr; J.t1 = (double)xt; return; }
  const F q = (F)1 / (F)steps;
  const F odz = (F)1 / dz, orho = (F)1 / rho;
  const double a = (double)odz, qd = (double)q, dtd = (double)dt, rd = (double)rho, da = -a * a;
  if (mode == 1) {
    xt = xt - S0 * odz * q * orho;
    const F pre = xr - S0 * odz * dt * q;
    J.t_s0 = -a * qd / rd;
    J.t_dz = -((double)S0 * qd / rd) * da;
    J.t_rho = (double)S0 * a * qd / (rd * rd);
    if (limit > pre) { J.x1 = (double)limit; J.x_x = 0.0; }
    else { J.x1 = (double)pre; J.x_s0 = -a * dtd * qd; J.x_dz = -(double)S0 * dtd * qd * da; }
    J.t1 = (double)xt;
    return;
  }
  xt = xt + S1 * ((F)1 / dz) * q / rho;
  xt = xt - S0 * odz * q * orho;
  J.t1 = (double)xt;
  J.t_s1 = a * qd / rd;
  J.t_s0 = -a * qd / rd;
  J.t_dz = ((double)S1 - (double)S0) * qd / rd * da;
  J.t_rho = -((double)S1 - (double)S0) * a * qd / (rd * rd);
  const F pre1 = xr + S1 * ((F)1 / dz) * dt * q;
  double gx = 1.0, gs1 = a * dtd * qd, gdz = (double)S1 * dtd * qd * da;
  F x1 = pre1;
  if (limit > pre1) { x1 = limit; gx = 0.0; gs1 = 0.0; gdz = 0.0; }
  const F pre2 = x1 - S0 * odz * dt * q;
  if (limit > pre2) { J.x1 = (double)limit; J.x_x = 0.0; return; }
  J.x1 = (double)pre2;
  J.x_x = gx; J.x_s1 = gs1; J.x_s0 = -a * dtd * qd; J.x_dz = gdz - (double)S0 * dtd * qd * da;
}

// Primal only (the forward itself, no partials): the same words as the x1 of t9_sed_level.
template<class F>
__host__ __device__ __forceinline__ F t9_sed_level_x(int mode, F xr, F S0, F S1, F dz, F limit, F dt, int steps) {
  if (mode == 0) return xr;
  const F q = (F)1 / (F)steps, odz = (F)1 / dz;
  if (mode == 1) { const F pre = xr - S0 * odz * dt * q; return limit > pre ? limit : pre; }
  const F pre1 = xr + S1 * ((F)1 / dz) * dt * q;
  const F x1 = limit > pre1 ? limit : pre1;
  const F pre2 = x1 - S0 * odz * dt * q;
  return limit > pre2 ? limit : pre2;
}

// Snow fall speed at an active level (rs > r1). melt = (prr_sml > 0). Inputs as the forward's types.
struct T9Vs { float vt; double d_rhof, d_smob, d_smoc, d_rs, d_rr, d_vtrr, d_vtboost; };
__device__ __forceinline__ void t9_snow_vt_level(const TempoParams& P, float rhof, double smob, double smoc, float rs,
                                                 float rr, float vtrr, float vtboost, bool melt, T9Vs& J) {
  const double xds = smoc / smob;
  const double mrat = 1.0f / xds;
  const double u1 = mrat * PS(lam0) + PS(fv_s), u2 = mrat * PS(lam1) + PS(fv_s);
  double ils1 = 1.0f / u1, ils2 = 1.0f / u2;
  const double c4 = (double)PA1(cse, 4), c10 = (double)PA1(cse, 10), c1 = (double)PA1(cse, 1), c7 = (double)PA1(cse, 7);
  const double mu = (double)PS(mu_s);
  const double t1 = PS(kap0) * PA1(csg, 4) * ::tempo_pow(ils1, c4);
  const double pm = ::tempo_pow(mrat, mu);
  const double t2 = PS(kap1) * pm * PA1(csg, 10) * ::tempo_pow(ils2, c10);
  ils1 = 1.0f / (mrat * PS(lam0));
  ils2 = 1.0f / (mrat * PS(lam1));
  const double t3 = PS(kap0) * PA1(csg, 1) * ::tempo_pow(ils1, c1);
  const double t4 = PS(kap1) * pm * PA1(csg, 7) * ::tempo_pow(ils2, c7);
  const float vts = rhof * PS(av_s) * (t1 + t2) / (t3 + t4);
  // d t_i / d mrat (x^y partials: y x^(y-1) = y z / x on these positive bases)
  const double lam0 = (double)PS(lam0), lam1 = (double)PS(lam1);
  const double dt1 = -t1 * c4 * lam0 / u1;
  const double dt2 = t2 * (mu / mrat - c10 * lam1 / u2);
  const double dt3 = -t3 * c1 / mrat;
  const double dt4 = t4 * (mu - c7) / mrat;
  const double N = t1 + t2, D = t3 + t4, ra = (double)rhof * (double)PS(av_s);
  const double dv_dm = ra * ((dt1 + dt2) / D - N * (dt3 + dt4) / (D * D));
  const double dv_drhof = (double)PS(av_s) * N / D;
  const double dm_dx = -1.0 / (xds * xds);
  const double dm_dsmoc = dm_dx / smob, dm_dsmob = dm_dx * (-smoc / (smob * smob));
  double gv;
  J.d_rs = J.d_rr = J.d_vtrr = J.d_vtboost = 0.0;
  if (melt) {
    const float sr = rs / (rs + rr);
    J.vt = vts * sr + (1.0f - sr) * vtrr;
    const double s = (double)rs + (double)rr, ds = 1.0 / (s * s);
    gv = (double)sr;
    const double gsr = (double)vts - (double)vtrr;
    J.d_rs = gsr * (double)rr * ds;
    J.d_rr = -gsr * (double)rs * ds;
    J.d_vtrr = 1.0 - (double)sr;
  } else {
    J.vt = vts * vtboost;
    gv = (double)vtboost;
    J.d_vtboost = (double)vts;
  }
  J.d_rhof = gv * dv_drhof;
  J.d_smob = gv * dv_dm * dm_dsmob;
  J.d_smoc = gv * dv_dm * dm_dsmoc;
}

// Ice fall speeds at an active level (ri > r1).
struct T9Vi { float vt, vtn; double vt_rhof, vt_ilam, vtn_rhof, vtn_ilam; };
__device__ __forceinline__ void t9_ice_vt_level(const TempoParams& P, float rhof, double ilami, T9Vi& J) {
  const double bv = (double)PS(bv_i);
  const double pi_ = ::tempo_pow(ilami, bv);
  J.vt = rhof * PS(av_i) * PA1(cig, 3) * PS(oig2) * pi_;
  J.vtn = rhof * PS(av_i) * PA1(cig, 6) / PA1(cig, 7) * pi_;
  const double cv = (double)PS(av_i) * (double)PA1(cig, 3) * (double)PS(oig2);
  const double cn = (double)PS(av_i) * (double)PA1(cig, 6) / (double)PA1(cig, 7);
  const double dp = (ilami != 0.0) ? bv * ::tempo_pow(ilami, bv - 1.0) : 0.0;
  J.vt_rhof = cv * pi_; J.vt_ilam = (double)rhof * cv * dp;
  J.vtn_rhof = cn * pi_; J.vtn_ilam = (double)rhof * cn * dp;
}

// Cloud fall speeds at a level k <= ktop with rc > r1 and w < 0.1. nu_c = get_nuc(nc) (integer: no derivative).
struct T9Vc { float vt, vtn; double vt_rhof, vt_ilam, vtn_rhof, vtn_ilam; };
__device__ __forceinline__ void t9_cloud_vt_level(const TempoParams& P, float rhof, double ilamc, int nu_c, T9Vc& J) {
  const double bv = (double)PS(bv_c);
  const double pc = ::tempo_pow(ilamc, bv);
  J.vt = rhof * PS(av_c) * PA2(ccg, 5, nu_c) * PA1(ocg2, nu_c) * pc;
  J.vtn = rhof * PS(av_c) * PA2(ccg, 4, nu_c) * PA1(ocg1, nu_c) * pc;
  const double cv = (double)PS(av_c) * (double)PA2(ccg, 5, nu_c) * (double)PA1(ocg2, nu_c);
  const double cn = (double)PS(av_c) * (double)PA2(ccg, 4, nu_c) * (double)PA1(ocg1, nu_c);
  const double dp = (ilamc != 0.0) ? bv * ::tempo_pow(ilamc, bv - 1.0) : 0.0;
  J.vt_rhof = cv * pc; J.vt_ilam = (double)rhof * cv * dp;
  J.vtn_rhof = cn * pc; J.vtn_ilam = (double)rhof * cn * dp;
}

// ============================================================================ Part B
// Warp-cooperative, 1-based arrays [0..nz+1] that every lane of the column's warp can read (shared memory, or the
// integrator's per-warp scratch). Lane L owns levels L+1, L+33, ...; T9_ROWS_MAX levels per lane at most.
#ifndef T9_ROWS_MAX
#define T9_ROWS_MAX ((TEMPO_NZ_MAX + 31) / 32)
#endif
#ifndef T9_ADJ_T
#define T9_ADJ_T double   // the fused reverse cotangent type (float: see t9_sed_rev_reg)
#endif
#define T9_LV(k, j, n) for (int k = 1 + (int)(threadIdx.x & 31u), j = 0; k <= (n); k += 32, ++j)
__device__ __forceinline__ int t9_mode(int k, int nz, int ktop) { return k == nz ? 1 : (k <= ktop ? 2 : 0); }

// Forward of one sedimentation() call on a value profile: x (in) -> y (out), no aliasing.
template<class F>
__device__ __forceinline__ void t9_sed_fwd_call(int nz, int ktop, int steps, F limit, F dt, const F* x, F* y,
                                                const F* vt, const F* dz, const F* rho) {
  T9_LV(k, j, nz) {
    const int m = t9_mode(k, nz, ktop);
    const F S0 = vt[k] * x[k], S1 = (m == 2) ? vt[k + 1] * x[k + 1] : (F)0;
    y[k] = t9_sed_level_x<F>(m, x[k], S0, S1, dz[k], limit, dt, steps);
  }
  __syncwarp();
}

// Reverse of `ncalls` sedimentation() calls of one species with fixed vt (snow: ncalls = steps = substeps; ice: 1 call,
// steps = substeps; cloud: 1, 1).
//   x0     the species profile before the first call (the stage checkpoint); read only.
//   hist   scratch, hcap >= 3 rows of (nz + 2) F: the profile before each call, recomputed (never a tape). When
//          ncalls - 1 > hcap, rows 0..hcap-3 hold the first calls' profiles and the last two rows are a ping-pong pair
//          for replaying later profiles from the last kept row (exact, O(ncalls^2/hcap) calls, no extra memory).
//   xbar   in: cotangent of the profile after the last call; out: before the first call.
//   tbar   cotangent of xten (pass-through, xten' = xten + g). pbar: the precip accumulator's (pass-through).
//   vtbar, dzbar, rhobar: +=.   cup: scratch (nz + 2) doubles.
template<class F>
__device__ void t9_sed_rev(int nz, int ktop, int steps, int ncalls, F limit, F dt, F low_limit, bool has_p,
                           const F* x0, const F* vt, const F* dz, const F* rho, F* hist, int hcap,
                           double* xbar, const double* tbar, double pbar, double* vtbar, double* dzbar,
                           double* rhobar, double* cup) {
  const F q = (F)1 / (F)steps;
  const double pdt = (double)dt * (double)q;   // d precip' / d sed_r[1] (the forward: precip + sed_r[1]*dt*(1/steps))
  const long long W = nz + 2;
  // profile before call n: n == 0 -> x0; 1 <= n <= keep -> hist row n-1; later -> replayed
  const bool fits = (ncalls - 1) <= hcap;
  const int keep = fits ? ncalls - 1 : hcap - 2;
  for (int n = 1; n <= keep; ++n)
    t9_sed_fwd_call<F>(nz, ktop, steps, limit, dt, n == 1 ? x0 : hist + (n - 2) * W, hist + (n - 1) * W, vt, dz, rho);
  F* pp[2] = {hist + (long long)(hcap - 2) * W, hist + (long long)(hcap - 1) * W};
  for (int n = ncalls - 1; n >= 0; --n) {
    const F* xn;
    if (n == 0) xn = x0;
    else if (n <= keep) xn = hist + (n - 1) * W;
    else {
      const F* src = keep == 0 ? x0 : hist + (keep - 1) * W;
      int w = 0;
      for (int m = keep; m < n; ++m) { t9_sed_fwd_call<F>(nz, ktop, steps, limit, dt, src, pp[w], vt, dz, rho); src = pp[w]; w ^= 1; }
      xn = src;
    }
    T9Sed Jr[T9_ROWS_MAX];
    T9_LV(k, j, nz) {
      const int m = t9_mode(k, nz, ktop);
      const F S0 = vt[k] * xn[k], S1 = (m == 2) ? vt[k + 1] * xn[k + 1] : (F)0;
      t9_sed_level<F>(m, xn[k], (F)0, S0, S1, dz[k], rho[k], limit, dt, steps, Jr[j]);
      cup[k] = (m == 2) ? Jr[j].x_s1 * xbar[k] + Jr[j].t_s1 * tbar[k] : 0.0;
    }
    __syncwarp();
    T9_LV(k, j, nz) {
      const T9Sed& J = Jr[j];
      double sb = J.x_s0 * xbar[k] + J.t_s0 * tbar[k] + (k >= 2 ? cup[k - 1] : 0.0);
      if (k == 1 && has_p && (F)J.x1 > low_limit) sb += pbar * pdt;
      dzbar[k] += J.x_dz * xbar[k] + J.t_dz * tbar[k];
      rhobar[k] += J.t_rho * tbar[k];
      vtbar[k] += sb * (double)xn[k];
      xbar[k] = J.x_x * xbar[k] + sb * (double)vt[k];
    }
    __syncwarp();
  }
}

// S1 of each owned level = S0 of the level above (lane + 1, or lane 0 of the next row); every lane takes part.
template<int R>
__device__ __forceinline__ void t9_reg_s1(int lane, const float* s0, float* s1) {
#pragma unroll
  for (int r = 0; r < R; ++r) {
    const float dn = __shfl_down_sync(0xffffffffu, s0[r], 1);
    const float nx = __shfl_sync(0xffffffffu, s0[r + 1 < R ? r + 1 : r], 0);
    s1[r] = lane < 31 ? dn : (r + 1 < R ? nx : 0.0f);
  }
}
// One sedimentation() call on a register profile (the forward words; mode per owned level in md).
template<int R>
__device__ __forceinline__ void t9_reg_call(int lane, const int* md, const float* vv, const float* odz, float limit,
                                            float dt, float q, float* x) {
  float s0[R], s1[R];
#pragma unroll
  for (int r = 0; r < R; ++r) s0[r] = vv[r] * x[r];
  t9_reg_s1<R>(lane, s0, s1);
#pragma unroll
  for (int r = 0; r < R; ++r) {
    const int m = md[r];
    if (m == 1) { const float pre = x[r] - s0[r] * odz[r] * dt * q; x[r] = limit > pre ? limit : pre; }
    else if (m == 2) {
      const float pre1 = x[r] + s1[r] * odz[r] * dt * q; const float x1 = limit > pre1 ? limit : pre1;
      const float pre2 = x1 - s0[r] * odz[r] * dt * q; x[r] = limit > pre2 ? limit : pre2;
    }
  }
}

// Register-resident form of t9_sed_rev (the one t9_rev_column uses; t9_sed_rev stays as the readable reference).
// Lane L holds levels 32r + L + 1 (r < R) in registers for the whole species: the profile, its cotangent, the
// per-level constants (one double division per level per species) and the vt/dz/rho cotangent sums. Level k reads
// level k+1 (S1) and level k-1 (the S1 cotangent) through warp shuffles, so nothing goes through memory per call
// except the per-call profile (one float per level per call, `hist`: hcap >= 1 rows of nz + 2 floats; calls past
// hcap are replayed in registers from the last kept row). dzbar may be null (dz carries no derivative).
template<int R, class A = double>
__device__ void t9_sed_rev_reg(int nz, int ktop, int steps, int ncalls, float limit, float dt, float low_limit,
                               bool has_p, const float* x0, const float* vt, const float* dz, const float* rho,
                               float* hist, int hcap, double* xbar, const double* tbar, double pbar, double* vtbar,
                               double* dzbar, double* rhobar) {
  const unsigned FULL = 0xffffffffu; const int lane = (int)(threadIdx.x & 31u);
  const float q = 1.0f / (float)steps;
  const A qd = (A)q, dtd = (A)dt, pdt = dtd * qd;
  float xv[R], vv[R], odz[R]; int md[R];
  A xb[R], tb[R], ar[R], ard[R], ctd[R], cxd[R], vb[R], zb[R], rb[R];
  const A cx_common = dtd * qd;
#pragma unroll
  for (int r = 0; r < R; ++r) {
    const int k = 32 * r + lane + 1; const bool ok = k <= nz;
    md[r] = ok ? t9_mode(k, nz, ktop) : 0;
    xv[r] = ok ? x0[k] : 0.0f; vv[r] = ok ? vt[k] : 0.0f;
    const float d = ok ? dz[k] : 1.0f, rh = ok ? rho[k] : 1.0f;
    odz[r] = 1.0f / d;
    const A a = (A)odz[r], ir = (A)1 / (A)rh, da = -a * a;
    ar[r] = a * qd * ir; ard[r] = ar[r] * ir; ctd[r] = qd * ir * da; cxd[r] = cx_common * da;
    xb[r] = ok ? (A)xbar[k] : (A)0; tb[r] = ok ? (A)tbar[k] : (A)0; vb[r] = 0; zb[r] = 0; rb[r] = 0;
  }
  const long long W = nz + 2;
  const int keep = (ncalls - 1) <= hcap ? ncalls - 1 : hcap;   // rows 0..keep-1: the profiles before calls 1..keep
  {
    float x[R];
#pragma unroll
    for (int r = 0; r < R; ++r) x[r] = xv[r];
    for (int n = 1; n <= keep; ++n) {
      t9_reg_call<R>(lane, md, vv, odz, limit, dt, q, x);
      float* h = hist + (long long)(n - 1) * W;
#pragma unroll
      for (int r = 0; r < R; ++r) { const int k = 32 * r + lane + 1; if (k <= nz) h[k] = x[r]; }
    }
  }
  __syncwarp();
  for (int n = ncalls - 1; n >= 0; --n) {
    float x[R];
    if (n == 0 || (n > keep && keep == 0)) {
#pragma unroll
      for (int r = 0; r < R; ++r) x[r] = xv[r];
    } else {
      const float* h = hist + (long long)((n <= keep ? n : keep) - 1) * W;
#pragma unroll
      for (int r = 0; r < R; ++r) { const int k = 32 * r + lane + 1; x[r] = k <= nz ? h[k] : 0.0f; }
    }
    for (int m = keep; m < n; ++m) t9_reg_call<R>(lane, md, vv, odz, limit, dt, q, x);
    float s0[R], s1[R];
#pragma unroll
    for (int r = 0; r < R; ++r) s0[r] = vv[r] * x[r];
    t9_reg_s1<R>(lane, s0, s1);
    A gxx[R], gs0[R], gt0[R], gdz[R], up[R]; float x1v[R];
#pragma unroll
    for (int r = 0; r < R; ++r) {
      const int m = md[r]; const A S0 = (A)s0[r], S1 = (A)s1[r];
      const A cx = (A)odz[r] * cx_common;
      gxx[r] = 1; gs0[r] = 0; gt0[r] = 0; gdz[r] = 0; up[r] = 0; x1v[r] = x[r];
      if (m == 1) {
        const float pre = x[r] - s0[r] * odz[r] * dt * q; const bool c = limit > pre; x1v[r] = c ? limit : pre;
        gxx[r] = c ? (A)0 : (A)1; gs0[r] = c ? (A)0 : -cx;
        gt0[r] = -ar[r];
        gdz[r] = (c ? (A)0 : -S0 * cxd[r]) * xb[r] - S0 * ctd[r] * tb[r];
        rb[r] += S0 * ard[r] * tb[r];
      } else if (m == 2) {
        const float pre1 = x[r] + s1[r] * odz[r] * dt * q; const bool c1 = limit > pre1; const float x1 = c1 ? limit : pre1;
        const float pre2 = x1 - s0[r] * odz[r] * dt * q; const bool c2 = limit > pre2; x1v[r] = c2 ? limit : pre2;
        gxx[r] = (c1 || c2) ? (A)0 : (A)1; gs0[r] = c2 ? (A)0 : -cx; gt0[r] = -ar[r];
        const A gs1 = (c1 || c2) ? (A)0 : cx;
        up[r] = gs1 * xb[r] + ar[r] * tb[r];
        gdz[r] = (c2 ? (A)0 : ((c1 ? (A)0 : S1) - S0) * cxd[r]) * xb[r] + (S1 - S0) * ctd[r] * tb[r];
        rb[r] += -(S1 - S0) * ard[r] * tb[r];
      }
    }
    // cotangent of S at level k from level k-1 (lane - 1, or lane 31 of the previous row)
#pragma unroll
    for (int r = 0; r < R; ++r) {
      const A u = __shfl_up_sync(FULL, up[r], 1);
      const A pv = __shfl_sync(FULL, up[r > 0 ? r - 1 : 0], 31);
      const A cin = lane > 0 ? u : (r > 0 ? pv : (A)0);
      A sb = gs0[r] * xb[r] + gt0[r] * tb[r] + cin;
      if (r == 0 && lane == 0 && has_p && x1v[0] > low_limit) sb += (A)pbar * pdt;
      zb[r] += gdz[r];
      vb[r] += sb * (A)x[r];
      xb[r] = gxx[r] * xb[r] + sb * (A)vv[r];
    }
  }
#pragma unroll
  for (int r = 0; r < R; ++r) {
    const int k = 32 * r + lane + 1;
    if (k <= nz) { xbar[k] = (double)xb[r]; vtbar[k] += (double)vb[r]; rhobar[k] += (double)rb[r]; if (dzbar) dzbar[k] += (double)zb[r]; }
  }
  __syncwarp();
}

// Inactive-level copies of a fall speed: vt[k] = vt[next active above k] for every inactive k (snow, ice). Folds
// the copies' cotangents into their source level, in fixed order (deterministic, no atomics). active(k) on bits.
__device__ __forceinline__ void t9_fold_copies(const unsigned* rows, int nz, double* vb) {
  T9_LV(k, j, nz) {
    if (!((rows[(k - 1) >> 5] >> ((k - 1) & 31)) & 1u)) continue;
    double s = 0.0;
    for (int i = k - 1; i >= 1 && !((rows[(i - 1) >> 5] >> ((i - 1) & 31)) & 1u); --i) s += vb[i];
    vb[k] += s;
  }
  __syncwarp();
  T9_LV(k, j, nz) if (!((rows[(k - 1) >> 5] >> ((k - 1) & 31)) & 1u)) vb[k] = 0.0;
  __syncwarp();
}

// The whole T9 reverse of one column. Entry state = the forward's arrays at the start of the snow section (T9 changes
// each species in its own section only, so this is every section's entry). Cotangents in = after T9, out = before T9
// (xbar arrays in place); the "+=" arrays accumulate. All arrays 1-based, warp-visible; scratch sized (nz + 2).
struct T9Col {
  const float *rs, *ri, *ni, *rc, *nc, *rhof, *rho, *dz, *rr, *vtrr, *vtboost, *w1d;
  const double *smob, *smoc, *prr_sml, *ilami, *ilamc;
  bool any_s, any_i, any_c;                          // tempo_any(l_qs / l_qi / l_qc) at each section's start
  double *b_rs, *b_ri, *b_ni, *b_rc, *b_nc;          // in/out
  const double *b_qsten, *b_qiten, *b_niten, *b_qcten, *b_ncten;   // pass-through cotangents of the tendencies
  double b_psnow, b_pice, b_pcloud;                  // precip accumulators (pass-through)
  double *b_rhof, *b_rho, *b_dz, *b_rr, *b_vtrr, *b_vtboost, *b_smob, *b_smoc, *b_ilami, *b_ilamc;  // +=
  float *vt, *vtn; double *vb, *vnb, *cup; float* hist; int hcap;  // scratch; hist: hcap >= 1 rows of (nz + 2); b_dz may be null
};
__device__ void t9_rev_column(const TempoParams& P, const TempoCtx& C, int nz, const T9Col& c) {
  const int lane = (int)(threadIdx.x & 31u);
  const float r1 = PS(r1), r2 = PS(r2), low = PS(low_limit_mass_for_precip), dt = C.global_dt;
  unsigned rows[T9_ROWS_MAX];
  // ---------------- cloud (last in the forward: first in reverse)
  if (c.any_c) {
    int ktop = 1;
    if (lane == 0) {
      float hgt = 0.0f;
      for (int k = 1; k <= nz - 1; ++k) { if (c.rc[k] > r2) ktop = k; hgt = hgt + c.dz[k]; if (hgt > 500.0f) break; }
    }
    ktop = __shfl_sync(0xffffffffu, ktop, 0);
    T9Vc Jc[T9_ROWS_MAX]; bool on[T9_ROWS_MAX];
    T9_LV(k, j, nz) {
      on[j] = (k <= ktop) && c.rc[k] > r1 && c.w1d[k] < 0.1f;
      if (on[j]) { t9_cloud_vt_level(P, c.rhof[k], c.ilamc[k], ::get_nuc(P, c.nc[k]), Jc[j]); c.vt[k] = Jc[j].vt; c.vtn[k] = Jc[j].vtn; }
      else { c.vt[k] = 0.0f; c.vtn[k] = 0.0f; }
      c.vb[k] = 0.0; c.vnb[k] = 0.0;
    }
    if (lane == 0) { c.vt[nz + 1] = 0.0f; c.vtn[nz + 1] = 0.0f; }
    __syncwarp();
    t9_sed_rev_reg<T9_ROWS_MAX, T9_ADJ_T>(nz, ktop, 1, 1, r2, dt, low, false, c.nc, c.vtn, c.dz, c.rho, c.hist, c.hcap, c.b_nc, c.b_ncten, 0.0, c.vnb, c.b_dz, c.b_rho);
    t9_sed_rev_reg<T9_ROWS_MAX, T9_ADJ_T>(nz, ktop, 1, 1, r1, dt, low, true, c.rc, c.vt, c.dz, c.rho, c.hist, c.hcap, c.b_rc, c.b_qcten, c.b_pcloud, c.vb, c.b_dz, c.b_rho);
    T9_LV(k, j, nz) if (on[j]) {
      c.b_rhof[k] += Jc[j].vt_rhof * c.vb[k] + Jc[j].vtn_rhof * c.vnb[k];
      c.b_ilamc[k] += Jc[j].vt_ilam * c.vb[k] + Jc[j].vtn_ilam * c.vnb[k];
    }
    __syncwarp();
  }
  // ---------------- ice
  if (c.any_i) {
    for (int r = 0; r < (nz + 31) / 32; ++r) { const int k = (r << 5) + lane + 1; rows[r] = __ballot_sync(0xffffffffu, k <= nz && c.ri[k] > r1); }
    T9Vi Ji[T9_ROWS_MAX];
    T9_LV(k, j, nz) if (c.ri[k] > r1) { t9_ice_vt_level(P, c.rhof[k], c.ilami[k], Ji[j]); c.vt[k] = Ji[j].vt; c.vtn[k] = Ji[j].vtn; }
    if (lane == 0) { c.vt[nz + 1] = 0.0f; c.vtn[nz + 1] = 0.0f; }
    __syncwarp();
    int ktop = 1, sub = 1;
    float vk[T9_ROWS_MAX], vnk[T9_ROWS_MAX];
    T9_LV(k, j, nz) {
      vk[j] = c.vt[k]; vnk[j] = c.vtn[k];
      if (!(c.ri[k] > r1)) { const int s = tempo_next_active(rows, k, nz); vk[j] = c.vt[s]; vnk[j] = c.vtn[s]; }
      if (vk[j] > 1.e-3f) { ktop = imax(ktop, k); const float dzv = c.dz[k] / vk[j]; sub = imax(sub, (int)(dt / dzv + 1.0f)); }
    }
    __syncwarp();
    T9_LV(k, j, nz) { c.vt[k] = vk[j]; c.vtn[k] = vnk[j]; c.vb[k] = 0.0; c.vnb[k] = 0.0; }
    ktop = tempo_warp_max(ktop); sub = tempo_warp_max(sub);
    ktop = (ktop == nz) ? nz - 1 : ktop;
    __syncwarp();
    t9_sed_rev_reg<T9_ROWS_MAX, T9_ADJ_T>(nz, ktop, sub, 1, r2, dt, low, false, c.ni, c.vtn, c.dz, c.rho, c.hist, c.hcap, c.b_ni, c.b_niten, 0.0, c.vnb, c.b_dz, c.b_rho);
    t9_sed_rev_reg<T9_ROWS_MAX, T9_ADJ_T>(nz, ktop, sub, 1, r1, dt, low, true, c.ri, c.vt, c.dz, c.rho, c.hist, c.hcap, c.b_ri, c.b_qiten, c.b_pice, c.vb, c.b_dz, c.b_rho);
    t9_fold_copies(rows, nz, c.vb); t9_fold_copies(rows, nz, c.vnb);
    T9_LV(k, j, nz) if (c.ri[k] > r1) {
      c.b_rhof[k] += Ji[j].vt_rhof * c.vb[k] + Ji[j].vtn_rhof * c.vnb[k];
      c.b_ilami[k] += Ji[j].vt_ilam * c.vb[k] + Ji[j].vtn_ilam * c.vnb[k];
    }
    __syncwarp();
  }
  // ---------------- snow (first in the forward: last in reverse)
  if (c.any_s) {
    for (int r = 0; r < (nz + 31) / 32; ++r) { const int k = (r << 5) + lane + 1; rows[r] = __ballot_sync(0xffffffffu, k <= nz && c.rs[k] > r1); }
    T9Vs Js[T9_ROWS_MAX]; bool melt[T9_ROWS_MAX];
    T9_LV(k, j, nz) if (c.rs[k] > r1) {
      melt[j] = c.prr_sml[k] > 0.0f;
      t9_snow_vt_level(P, c.rhof[k], c.smob[k], c.smoc[k], c.rs[k], c.rr[k], c.vtrr[k], c.vtboost[k], melt[j], Js[j]);
      c.vt[k] = Js[j].vt;
    }
    if (lane == 0) c.vt[nz + 1] = 0.0f;
    __syncwarp();
    int ktop = 1, sub = 1; float vk[T9_ROWS_MAX];
    T9_LV(k, j, nz) {
      vk[j] = c.vt[k];
      if (!(c.rs[k] > r1)) vk[j] = c.vt[tempo_next_active(rows, k, nz)];
      if (vk[j] > 1.e-3f) { ktop = imax(ktop, k); const float dzv = c.dz[k] / vk[j]; sub = imax(sub, (int)(dt / dzv + 1.0f)); }
    }
    __syncwarp();
    T9_LV(k, j, nz) { c.vt[k] = vk[j]; c.vb[k] = 0.0; }
    ktop = tempo_warp_max(ktop); sub = tempo_warp_max(sub);
    ktop = (ktop == nz) ? nz - 1 : ktop;
    __syncwarp();
    t9_sed_rev_reg<T9_ROWS_MAX, T9_ADJ_T>(nz, ktop, sub, sub, r1, dt, low, true, c.rs, c.vt, c.dz, c.rho, c.hist, c.hcap, c.b_rs, c.b_qsten, c.b_psnow, c.vb, c.b_dz, c.b_rho);
    t9_fold_copies(rows, nz, c.vb);
    T9_LV(k, j, nz) if (c.rs[k] > r1) {
      const T9Vs& J = Js[j]; const double g = c.vb[k];
      c.b_rhof[k] += J.d_rhof * g; c.b_smob[k] += J.d_smob * g; c.b_smoc[k] += J.d_smoc * g;
      c.b_rs[k] += J.d_rs * g; c.b_rr[k] += J.d_rr * g; c.b_vtrr[k] += J.d_vtrr * g; c.b_vtboost[k] += J.d_vtboost * g;
    }
    __syncwarp();
  }
}
#undef T9_LV

// ============================================================================ Part C (swap vehicle)
#ifdef T9_HAVE_AR
#if !TEMPO_WARP
#error "T9 vehicle: warp shape only"
#endif
template<class T> __device__ __forceinline__ AR<T> t9p(const AR<T>& x) { return ad_mk(x.v, 0); }
// y = sum_j g[j] x_j as max(1, m-1) nodes (m = active inputs with a nonzero partial); 0 when none.
template<int N> __device__ __forceinline__ int t9_emit(const int* ix, const double* g) {
  int r = 0, a = 0; double pa = 0.0;
  for (int j = 0; j < N; ++j) {
    if (!ix[j] || g[j] == 0.0) continue;
    if (r) r = ad_push(r, 1.0, ix[j], g[j]);
    else if (a) r = ad_push(a, pa, ix[j], g[j]);
    else { a = ix[j]; pa = g[j]; }
  }
  if (!r && a) r = ad_push(a, pa, 0, 0.0);
  return r;
}

TEMPO_HDN inline void t9_sedimentation(const TempoParams& P, const TempoCtx& C, int nz,
    AR<float>* xr, const AR<float>* vt, const AR<float>* dz1d, const AR<float>* rho, AR<float>* xten,
    AR<float> limit, int steps, int ktop_sedi, AR<float>* precip, AR<float>* sed_r) {
  const int ktop = ktop_sedi;
  TEMPO_SYNC();
  TEMPO_LEVELS(k, nz) sed_r[k] = vt[k] * xr[k];   // one node per level, as the forward
  TEMPO_SYNC();
  TEMPO_LEVELS(k, nz) {
    const int m = (k == nz) ? 1 : (k <= ktop ? 2 : 0);
    if (!m) continue;
    // the forward's statements on value-only copies: the same words and the same branch log
    AR<float> px = t9p(xr[k]), pt = t9p(xten[k]); AR<float> odz, orho;
    const AR<float> s0 = t9p(sed_r[k]), d = t9p(dz1d[k]), r = t9p(rho[k]);
    if (m == 1) {
      odz = 1.0f / d; orho = 1.0f / r;
      pt = pt - s0 * odz * (1.0f / (AR<float> )steps) * orho;
      px = tmax(limit, px - s0 * odz * C.global_dt * (1.0f / (AR<float> )steps));
    } else {
      const AR<float> s1 = t9p(sed_r[k + 1]);
      odz = 1.0f / d; orho = 1.0f / r;
      pt = pt + (s1) * (1.0f / d) * (1.0f / (AR<float> )steps) / r;
      pt = pt - (s0) * odz * (1.0f / (AR<float> )steps) * orho;
      px = tmax(limit, px + (s1) * (1.0f / d) * C.global_dt * (1.0f / (AR<float> )steps));
      px = tmax(limit, px - (s0) * odz * C.global_dt * (1.0f / (AR<float> )steps));
    }
    T9Sed J;
    t9_sed_level<float>(m, xr[k].v, xten[k].v, sed_r[k].v, m == 2 ? sed_r[k + 1].v : 0.0f, dz1d[k].v, rho[k].v,
                        limit.v, C.global_dt, steps, J);
    const int s1i = (m == 2) ? sed_r[k + 1].i : 0;
    const int ix[4] = {xr[k].i, s1i, sed_r[k].i, dz1d[k].i};
    const double gx[4] = {J.x_x, J.x_s1, J.x_s0, J.x_dz};
    const int it[5] = {xten[k].i, s1i, sed_r[k].i, dz1d[k].i, rho[k].i};
    const double gt[5] = {1.0, J.t_s1, J.t_s0, J.t_dz, J.t_rho};
    xr[k] = ad_mk(px.v, t9_emit<4>(ix, gx));
    xten[k] = ad_mk(pt.v, t9_emit<5>(it, gt));
  }
  if (TEMPO_LEAD && precip != nullptr) {
    if (xr[1] > PS(low_limit_mass_for_precip)) {
      const AR<float> pp = t9p(*precip) + t9p(sed_r[1]) * C.global_dt * (1.0f / (AR<float> )steps);
      const int ip[2] = {precip->i, sed_r[1].i};
      const double gp[2] = {1.0, (double)C.global_dt * (double)(1.0f / (float)steps)};
      *precip = ad_mk(pp.v, t9_emit<2>(ip, gp));
    }
  }
  TEMPO_SYNC();
}

TEMPO_HDN inline void t9_snow_fallspeed(const TempoParams& P, const TempoCtx& C, int nz,
    const AR<float>* rhof, const bool* l_qs, const AR<float>* rs, const AR<double>* prr_sml,
    const AR<double>* smob, const AR<double>* smoc, const AR<float>* rr, const AR<float>* vtrr,
    const AR<float>* dz1d, AR<float>* vt, const AR<float>* vtboost, int* substeps_sedi, int* ktop_sedi) {
  AR<float> dz_by_vt; AR<float>  vts; AR<float>  sr; AR<double>  xds; AR<double>  mrat; AR<double>  ils1; AR<double>  ils2; AR<double>  t1_vts; AR<double>  t2_vts; AR<double>  t3_vts; AR<double>  t4_vts;
  unsigned rows[TEMPO_ROWS];
  TEMPO_SYNC();
  TEMPO_BALLOT_ROWS(rows, rs[k] > PS(r1))
  const int active_count=tempo_active_count(rows,nz);
  for(int rank=TEMPO_LANE;rank<active_count;rank+=32) {
    const int k=tempo_active_level(rows,rank,nz);
    if (rs[k] > PS(r1)) {
      xds = t9p(smoc[k]) / t9p(smob[k]);
      mrat = 1.0f / xds;
      ils1 = 1.0f / (mrat * PS(lam0) + PS(fv_s));
      ils2 = 1.0f / (mrat * PS(lam1) + PS(fv_s));
      t1_vts = PS(kap0) * PA1(csg, 4) * tempo_pow(ils1, PA1(cse, 4));
      const AR<double> pm = tempo_pow(mrat, PS(mu_s));
      t2_vts = PS(kap1) * pm * PA1(csg, 10) * tempo_pow(ils2, PA1(cse, 10));
      ils1 = 1.0f / (mrat * PS(lam0));
      ils2 = 1.0f / (mrat * PS(lam1));
      t3_vts = PS(kap0) * PA1(csg, 1) * tempo_pow(ils1, PA1(cse, 1));
      t4_vts = PS(kap1) * pm * PA1(csg, 7) * tempo_pow(ils2, PA1(cse, 7));
      vts = t9p(rhof[k]) * PS(av_s) * (t1_vts + t2_vts) / (t3_vts + t4_vts);
      AR<float> v;
      bool melt;
      if (prr_sml[k] > 0.0f) {
        sr = t9p(rs[k]) / (t9p(rs[k]) + t9p(rr[k]));
        v = vts * sr + (1.0f - sr) * t9p(vtrr[k]);
        melt = true;
      } else {
        v = vts * t9p(vtboost[k]);
        melt = false;
      }
      T9Vs J;
      t9_snow_vt_level(P, rhof[k].v, smob[k].v, smoc[k].v, rs[k].v, rr[k].v, vtrr[k].v, vtboost[k].v, melt, J);
      const int ix[7] = {rhof[k].i, smob[k].i, smoc[k].i, rs[k].i, rr[k].i, vtrr[k].i, vtboost[k].i};
      const double g[7] = {J.d_rhof, J.d_smob, J.d_smoc, J.d_rs, J.d_rr, J.d_vtrr, J.d_vtboost};
      vt[k] = ad_mk(v.v, t9_emit<7>(ix, g));
    }
  }
  TEMPO_SYNC();
  int ktop = 1, substeps = 1;
  TEMPO_LEVELS(k, nz) {
    if (!(rs[k] > PS(r1))) vt[k] = vt[tempo_next_active(rows, k, nz)];
    if (vt[k] > 1.e-3f) {
      ktop = imax(ktop, k);
      dz_by_vt = t9p(dz1d[k]) / t9p(vt[k]);   // feeds an integer only: value-only (the forward taped 3 dead nodes)
      substeps = imax(substeps, (int)(C.global_dt / dz_by_vt + 1.0f));
    }
  }
  ktop = tempo_warp_max(ktop);
  substeps = tempo_warp_max(substeps);
  if (ktop_sedi) *ktop_sedi = (ktop == nz) ? nz - 1 : ktop;
  if (substeps_sedi) *substeps_sedi = substeps;
  TEMPO_SYNC();
}

TEMPO_HDN inline void t9_ice_fallspeed(const TempoParams& P, const TempoCtx& C, int nz,
    const AR<float>* rhof, const bool* l_qi, const AR<float>* ri, const AR<double>* ilami,
    const AR<float>* dz1d, AR<float>* vt, AR<float>* vtn, int* substeps_sedi, int* ktop_sedi) {
  AR<float> dz_by_vt;
  unsigned rows[TEMPO_ROWS];
  TEMPO_SYNC();
  TEMPO_BALLOT_ROWS(rows, ri[k] > PS(r1))
  const int active_count=tempo_active_count(rows,nz);
  for(int rank=TEMPO_LANE;rank<active_count;rank+=32) {
    const int k=tempo_active_level(rows,rank,nz);
    if (ri[k] > PS(r1)) {
      const AR<double> pi_ = tempo_pow(t9p(ilami[k]), PS(bv_i));
      const AR<float> v = t9p(rhof[k]) * PS(av_i) * PA1(cig, 3) * PS(oig2) * pi_;
      const AR<float> vn = t9p(rhof[k]) * PS(av_i) * PA1(cig, 6) / PA1(cig, 7) * pi_;
      T9Vi J; t9_ice_vt_level(P, rhof[k].v, ilami[k].v, J);
      const int ix[2] = {rhof[k].i, ilami[k].i};
      const double g[2] = {J.vt_rhof, J.vt_ilam}, gn[2] = {J.vtn_rhof, J.vtn_ilam};
      vt[k] = ad_mk(v.v, t9_emit<2>(ix, g));
      vtn[k] = ad_mk(vn.v, t9_emit<2>(ix, gn));
    }
  }
  TEMPO_SYNC();
  int ktop = 1, substeps = 1;
  TEMPO_LEVELS(k, nz) {
    if (!(ri[k] > PS(r1))) {
      const int j = tempo_next_active(rows, k, nz);
      vt[k] = vt[j];
      vtn[k] = vtn[j];
    }
    if (vt[k] > 1.e-3f) {
      ktop = imax(ktop, k);
      dz_by_vt = t9p(dz1d[k]) / t9p(vt[k]);
      substeps = imax(substeps, (int)(C.global_dt / dz_by_vt + 1.0f));
    }
  }
  ktop = tempo_warp_max(ktop);
  *substeps_sedi = tempo_warp_max(substeps);
  *ktop_sedi = (ktop == nz) ? nz - 1 : ktop;
  TEMPO_SYNC();
}

TEMPO_HDN inline void t9_cloud_fallspeed(const TempoParams& P, const TempoCtx& C, int nz,
    const AR<float>* rhof, const AR<float>* w1d, const bool* l_qc, const AR<float>* rc,
    const AR<float>* nc, const AR<double>* ilamc, const AR<float>* dz1d, AR<float>* vt, AR<float>* vtn,
    int* ktop_sedi) {
  AR<float> hgt;
  int nu_c;
  TEMPO_SYNC();
  int ktop = 1;
  if (TEMPO_LEAD) {
    hgt = 0.0f;
    for (int k = 1; k <= nz - 1; ++k) {
      if (rc[k] > PS(r2)) ktop = k;
      hgt = hgt + t9p(dz1d[k]);   // feeds an integer only (value-only)
      if (hgt > 500.0f) break;
    }
  }
  *ktop_sedi = ktop = __shfl_sync(TEMPO_FULL, ktop, 0);
  TEMPO_LEVELS(k, ktop) {
    if (rc[k] > PS(r1) && w1d[k] < 0.1f) {
      nu_c = get_nuc(P, nc[k]);
      const AR<double> pc = tempo_pow(t9p(ilamc[k]), PS(bv_c));
      const AR<float> v = t9p(rhof[k]) * PS(av_c) * PA2(ccg, 5, nu_c) * PA1(ocg2, nu_c) * pc;
      const AR<float> vn = t9p(rhof[k]) * PS(av_c) * PA2(ccg, 4, nu_c) * PA1(ocg1, nu_c) * pc;
      T9Vc J; t9_cloud_vt_level(P, rhof[k].v, ilamc[k].v, nu_c, J);
      const int ix[2] = {rhof[k].i, ilamc[k].i};
      const double g[2] = {J.vt_rhof, J.vt_ilam}, gn[2] = {J.vtn_rhof, J.vtn_ilam};
      vt[k] = ad_mk(v.v, t9_emit<2>(ix, g));
      vtn[k] = ad_mk(vn.v, t9_emit<2>(ix, gn));
    }
  }
  TEMPO_SYNC();
}
#endif  // T9_HAVE_AR
#endif  // T9_SEDI_SIC_CUH

