TEMPO_HDN __noinline__ void split_rain(const TempoParams& P, const TempoCtx& C, int nz,
    const AR<float>* rho, bool* l_qr, AR<float>* qr1d, AR<float>* nr1d, AR<float>* rr, AR<float>* nr,
    AR<float>* qrten, AR<float>* nrten, AR<double>* ilamr, AR<float>* mvd_r, int last) {
  TEMPO_LEVELS(k,nz) {
    const T2Rain x = {qr1d[k].v,nr1d[k].v,qrten[k].v,nrten[k].v,rho[k].v};
    const float xv[5] = {x.qr1d,x.nr1d,x.qrten,x.nrten,x.rho};
    const int ix[5] = {qr1d[k].i,nr1d[k].i,qrten[k].i,nrten[k].i,rho[k].i};
    T2RainBar b = {}; T2RainOut y;
    ::t2r_rain(P,C,x,b,&y);
    const int e = split_checkpoint(P,C,-20,xv,ix,5,0);
    int id[6];
    for(int j=0;j<6;++j) id[j] = e ? e+32*(j+1) : 0;
    l_qr[k]=y.l_qr; rr[k]=ad_mk(y.rr,id[0]); nr[k]=ad_mk(y.nr,id[1]);
    ilamr[k]=ad_mk(y.ilamr,id[2]); qrten[k]=ad_mk(y.qrten,id[3]); nrten[k]=ad_mk(y.nrten,id[4]);
    mvd_r[k]=ad_mk(y.mvd_r,last?id[5]:0);
    qr1d[k]=ad_mk(y.qr1d,0); nr1d[k]=ad_mk(y.nr1d,0);
  }
}
TEMPO_HDN __noinline__ void split_graupel(const TempoParams& P, const TempoCtx& C, int nz,
    const AR<float>* rho, bool* l_qg, AR<float>* qg1d, AR<float>* ng1d, AR<float>* qb1d, AR<float>* rg,
    AR<float>* ng, AR<float>* rb, int* idx, AR<float>* qgten, AR<float>* ngten, AR<float>* qbten,
    AR<double>* ilamg, AR<float>* mvd_g, int last) {
  const bool hb = ng1d && qb1d;
  TEMPO_LEVELS(k,nz) {
    const T2Graupel x={qg1d[k].v,hb?ng1d[k].v:0.0f,hb?qb1d[k].v:0.0f,qgten[k].v,ngten[k].v,qbten[k].v,rho[k].v,hb};
    const float xv[7]={x.qg1d,x.ng1d,x.qb1d,x.qgten,x.ngten,x.qbten,x.rho};
    const int ix[7]={qg1d[k].i,hb?ng1d[k].i:0,hb?qb1d[k].i:0,qgten[k].i,ngten[k].i,qbten[k].i,rho[k].i};
    T2GraupelBar b={}; T2GraupelOut y;
    ::t2r_graupel(P,C,x,b,&y);
    const int e=split_checkpoint(P,C,-21,xv,ix,7,hb);
    int id[8]; for(int j=0;j<8;++j) id[j]=e?e+32*(j+1):0;
    l_qg[k]=y.l_qg; idx[k]=y.idx; rg[k]=ad_mk(y.rg,id[0]); ng[k]=ad_mk(y.ng,id[1]);
    rb[k]=ad_mk(y.rb,id[2]); ilamg[k]=ad_mk(y.ilamg,id[3]); qgten[k]=ad_mk(y.qgten,id[4]);
    mvd_g[k]=ad_mk(y.mvd_g,last?id[7]:0); qg1d[k]=ad_mk(y.qg1d,0);
    if(hb) {ngten[k]=ad_mk(y.ngten,id[5]); qbten[k]=ad_mk(y.qbten,id[6]);
      ng1d[k]=ad_mk(y.ng1d,0); qb1d[k]=ad_mk(y.qb1d,0);}
  }
}

